 166: func debugCommandName(args []string) string {
 167: 	if len(args) == 0 {
 168: 		return "cnm"
 169: 	}
 170: 	for _, arg := range args {
 171: 		if arg == "--json" {
 172: 			continue
 173: 		}
 174: 		if arg == "--help" || arg == "-h" {
 175: 			return "cnm help"
 176: 		}
 177: 		if arg == "--version" || arg == "-version" {
 178: 			return "cnm version"
 179: 		}
 180: 		break
 181: 	}
 182: 	command, _ := resolveCommand(args)
 183: 	switch command {
 184: 	case "":
 185: 		return "cnm"
 186: 	case "auto":
 187: 		return "cnm auto"
 188: 	case "init":
 189: 		return "cnm init"
 190: 	case "config":
 191: 		return "cnm config"
 192: 	case "doctor":
 193: 		return "cnm doctor"
 194: 	case "help":
 195: 		return "cnm help"
 196: 	case "split", "repair", "check", "onboard":
 197: 		return "removed"
 198: 	default:
 199: 		return "unknown"
 200: 	}
 201: }
