 263: func doctorRichRenderer() func(doctor.Report) string {
 264: 	return func(report doctor.Report) string {
 265: 		view := buildDoctorView(report)
 266: 		width := terminalWidth()
 267: 		return tui.RenderDoctorRich(view, width, false)
 268: 	}
 269: }
