 417: func currentConfigPanelProvider(runtime Runtime) (config.ProviderType, error) {
 418: 	resolved, err := config.ResolveEffectiveConfig(config.ResolveConfigOptions{
 419: 		CWD:         runtime.CWD,
 420: 		Env:         runtime.Env,
 421: 		SecretStore: runtime.SecretStore,
 422: 	})
 423: 	if err != nil {
 424: 		return "", err
 425: 	}
 426: 	return resolved.Values.Provider, nil
 427: }
