 871: func allowedPathSet(paths []string) map[string]bool {
 872: 	allowed := map[string]bool{}
 873: 	for _, path := range paths {
 874: 		if normalized, err := normalizeRepoRelativePath(path); err == nil {
 875: 			allowed[normalized] = true
 876: 		}
 877: 	}
 878: 	return allowed
