 881: func requireAllowedRepairPath(rawPath string, allowed map[string]bool) (string, error) {
 882: 	path, err := normalizeRepoRelativePath(rawPath)
 883: 	if err != nil {
 884: 		return "", err
 885: 	}
 886: 	if !allowed[path] {
 887: 		return "", fmt.Errorf("path is not eligible for Interactive Repair: %s", path)
 888: 	}
 889: 	return path, nil
 890: }
