1062: 	parts := []string{
1063: 		"You are running cnm Autonomous Commit.",
1064: 		"Use only the provided Domain Tools. Do not request shell access, raw git commands, or JSON plans.",
1065: 		"Start by calling inspect_commit_scope. Use get_diff and bounded read_file when needed before choosing commits.",
