 717: func conflictFilePaths(scope gitpkg.CommitScope) []string {
 718: 	paths := make([]string, 0)
 719: 	for _, file := range scope.Files {
 720: 		if scopeFileHasConflict(file) {
 721: 			paths = append(paths, file.Path)
 722: 		}
 723: 	}
 724: 	return paths
 725: }
 726: 
 727: func executeInteractiveRepair(runtime Runtime, scope gitpkg.CommitScope, resolvedConfig config.EffectiveConfig, reason string) error {
 728: 	provider, err := resolveRepairProvider(runtime, scope, resolvedConfig, reason)
 729: 	if err != nil {
 730: 		return err
 731: 	}
 732: 	eligiblePaths := conflictFilePaths(scope)
 733: 	if len(eligiblePaths) == 0 {
 734: 		return fmt.Errorf("Interactive Repair requires at least one eligible conflicted file")
 735: 	}
 736: 	repairRuntime := runtimex.NewToolCallRuntime(runtimex.ToolCallRuntimeOptions{
 737: 		Provider:      provider,
 738: 		ContextPolicy: scope.ContextPolicy,
 739: 		Tools:         interactiveRepairDomainTools(runtime, scope, eligiblePaths),
 740: 		RepairPolicy: runtimex.RepairPolicy{
 741: 			AllowedPaths: eligiblePaths,
 742: 			ConfirmWrite: func(input runtimex.RepairFileInput) (bool, error) {
 743: 				return true, nil
 744: 			},
 745: 		},
 746: 	})
 747: 	result, err := repairRuntime.Run()
 748: 	if err != nil {
 749: 		return err
 750: 	}
 751: 	if result.Status != runtimex.RunStatusCompleted {
 752: 		return fmt.Errorf("Interactive Repair did not complete: %s", firstNonEmptyString(result.Message, result.LimitReason, string(result.Status)))
 753: 	}
 754: 	return nil
 755: }
 756: 
 757: func resolveRepairProvider(runtime Runtime, scope gitpkg.CommitScope, resolvedConfig config.EffectiveConfig, reason string) (runtimex.ToolCallProvider, error) {
 758: 	if runtime.RepairProvider != nil {
 759: 		return runtime.RepairProvider, nil
 760: 	}
 761: 	providerConfig := providers.ProviderConfig{
 762: 		Provider:   resolvedConfig.Provider,
 763: 		APIKey:     resolvedConfig.APIKey,
 764: 		BaseURL:    resolvedConfig.BaseURL,
 765: 		Model:      resolvedConfig.Model,
 766: 		HTTPClient: runtime.ProviderHTTPClient,
 767: 	}
 768: 	return providers.CreateToolCallProvider(providers.ToolCallProviderOptions{
 769: 		Config:       providerConfig,
 770: 		Instructions: interactiveRepairInstructions(resolvedConfig),
 771: 		Input:        interactiveRepairInput(scope, reason),
 772: 		Tools: []runtimex.ToolName{
 773: 			runtimex.ToolInspectCommitScope,
 774: 			runtimex.ToolGetDiff,
 775: 			runtimex.ToolReadFile,
 776: 			runtimex.ToolPreviewCommit,
 777: 			runtimex.ToolRepairFile,
 778: 			runtimex.ToolFinish,
 779: 			runtimex.ToolAbort,
 780: 		},
 781: 	})
 782: }
