 784: func interactiveRepairInstructions(resolvedConfig config.EffectiveConfig) string {
 785: 	parts := []string{
 786: 		"You are running cnm Interactive Repair inside the Full-screen TUI.",
 787: 		"Use only the provided Domain Tools. Do not request shell access or low-level git commands.",
 788: 		"Read each file with read_file before repair_file. Repair only eligible conflicted files.",
 789: 		"After applying necessary repairs, call finish. If the conflict cannot be resolved safely, call abort with a clear message.",
 790: 	}
 791: 	if resolvedConfig.StandingInstruction != nil && strings.TrimSpace(*resolvedConfig.StandingInstruction) != "" {
 792: 		parts = append(parts, "Standing Instruction: "+strings.TrimSpace(*resolvedConfig.StandingInstruction))
 793: 	}
 794: 	if strings.TrimSpace(string(resolvedConfig.MessageLanguage)) != "" {
 795: 		parts = append(parts, "Message Language: "+string(resolvedConfig.MessageLanguage))
 796: 	}
 797: 	return strings.Join(parts, "\n")
 798: }
