 907: func repoFilePath(cwd string, relativePath string) (string, error) {
 908: 	base, err := filepath.Abs(cwd)
 909: 	if err != nil {
 910: 		return "", err
 911: 	}
 912: 	joined := filepath.Join(base, filepath.FromSlash(relativePath))
 913: 	absolute, err := filepath.Abs(joined)
 914: 	if err != nil {
 915: 		return "", err
 916: 	}
 917: 	rel, err := filepath.Rel(base, absolute)
 918: 	if err != nil {
 919: 		return "", err
 920: 	}
 921: 	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
 922: 		return "", fmt.Errorf("path must stay inside the repository: %s", relativePath)
 923: 	}
 924: 	return absolute, nil
 925: }
