 800: func interactiveRepairInput(scope gitpkg.CommitScope, reason string) string {
 801: 	lines := []string{"Interactive Repair request.", "Reason: " + reason, "Eligible conflicted files:"}
 802: 	for _, path := range conflictFilePaths(scope) {
 803: 		lines = append(lines, "- "+path)
 804: 	}
 805: 	if len(scope.Pathspecs) > 0 {
 806: 		lines = append(lines, "Commit Scope pathspecs:")
 807: 		for _, pathspec := range scope.Pathspecs {
 808: 			lines = append(lines, "- "+pathspec)
 809: 		}
 810: 	}
 811: 	return strings.Join(lines, "\n")
 812: }
