 892: func normalizeRepoRelativePath(rawPath string) (string, error) {
 893: 	trimmed := strings.TrimSpace(rawPath)
 894: 	if trimmed == "" {
 895: 		return "", fmt.Errorf("path is required")
 896: 	}
 897: 	if filepath.IsAbs(trimmed) || strings.HasPrefix(strings.ReplaceAll(trimmed, "\\", "/"), "/") {
 898: 		return "", fmt.Errorf("absolute paths are not allowed: %s", rawPath)
 899: 	}
 900: 	cleaned := pathpkg.Clean(strings.ReplaceAll(trimmed, "\\", "/"))
 901: 	if cleaned == "." || cleaned == ".." || strings.HasPrefix(cleaned, "../") {
 902: 		return "", fmt.Errorf("path must stay inside the repository: %s", rawPath)
 903: 	}
 904: 	return cleaned, nil
 905: }
 906: 
 907: func repoFilePath(cwd string, relativePath string) (string, error) {
 908: 	base, err := filepath.Abs(cwd)
 909: 	if err != nil {
 910: 		return "", err
 911: 	}
 912: 	joined := filepath.Join(base, filepath.FromSlash(relativePath))
 913: 	absolute, err := filepath.Abs(joined)
 914: 	if err != nil {
 915: 		return "", err
 916: 	}
 917: 	rel, err := filepath.Rel(base, absolute)
 918: 	if err != nil {
 919: 		return "", err
 920: 	}
 921: 	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
 922: 		return "", fmt.Errorf("path must stay inside the repository: %s", relativePath)
 923: 	}
 924: 	return absolute, nil
 925: }
