743: func changeKind(status byte) *ChangeKind {
744: 	var kind ChangeKind
745: 	switch status {
746: 	case 'A':
747: 		kind = ChangeAdded
748: 	case 'C':
749: 		kind = ChangeCopied
750: 	case 'D':
751: 		kind = ChangeDeleted
752: 	case 'M':
753: 		kind = ChangeModified
754: 	case 'R':
755: 		kind = ChangeRenamed
756: 	case 'T':
757: 		kind = ChangeTypechange
758: 	case 'U':
759: 		kind = ChangeUnmerged
760: 	case '?':
761: 		kind = ChangeUnknown
762: 	case ' ':
763: 		return nil
764: 	default:
765: 		if status == 0 {
766: 			return nil
767: 		}
768: 		kind = ChangeUnknown
769: 	}
770: 	return &kind
771: }
