640: func applyWorkingTreeBinaryMetadata(cwd string, files []FileStatus) []FileStatus {
641: 	result := make([]FileStatus, 0, len(files))
642: 	for _, file := range files {
643: 		if file.Binary || file.Staged != nil && file.Unstaged == nil && !file.Untracked {
644: 			result = append(result, file)
645: 			continue
646: 		}
647: 		if workingTreeFileLooksBinary(filepath.Join(cwd, file.Path)) {
648: 			file.Binary = true
649: 		}
650: 		result = append(result, file)
651: 	}
652: 	return result
653: }
