409: func RollbackCommitTransaction(cwd string, env map[string]string, snapshot CommitTransactionSnapshot, gitRunner CommandRunner) CommitTransactionRollbackResult {
410: 	if gitRunner == nil {
411: 		gitRunner = DefaultCommandRunner
412: 	}
413: 	if strings.TrimSpace(snapshot.Head) == "" {
414: 		return CommitTransactionRollbackResult{RolledBack: false, Status: "unsafe", Message: "missing transaction start head"}
415: 	}
416: 	resetResult := normalizeRunnerResult(gitRunner(cwd, []string{"reset", "--mixed", snapshot.Head}, env))
417: 	if resetResult.ExitCode != 0 {
418: 		return CommitTransactionRollbackResult{RolledBack: false, Status: "failed", Message: firstNonEmpty(resetResult.Stderr, resetResult.Stdout, "git reset failed")}
419: 	}
420: 	statusResult := normalizeRunnerResult(gitRunner(cwd, []string{"status", "--porcelain=v1", "-z", "--untracked-files=all"}, env))
421: 	if statusResult.ExitCode != 0 {
422: 		return CommitTransactionRollbackResult{RolledBack: true, Status: "rolled_back", Message: "rollback status verification failed"}
423: 	}
424: 	if statusResult.Stdout != snapshot.Status {
425: 		return CommitTransactionRollbackResult{RolledBack: true, Status: "rolled_back_with_status_change", Message: "working tree state differs from transaction start"}
426: 	}
427: 	return CommitTransactionRollbackResult{RolledBack: true, Status: "rolled_back"}
428: }
