517: func buildIssues(repository RepositoryState, files []FileStatus, diff DiffMetadata) []Issue {
518: 	issues := make([]Issue, 0)
519: 	if !repository.IsRepository {
520: 		issues = append(issues, createIssue("not_git_repository", "Current directory is not inside a git repository.", IssueSeverityBlocking))
521: 		return issues
522: 	}
523: 	if repository.IsBare {
524: 		issues = append(issues, createIssue("bare_repository", "Bare git repositories are not supported by this workflow.", IssueSeverityBlocking))
525: 	}
526: 	if repository.MergeInProgress {
527: 		issues = append(issues, createIssue("merge_in_progress", "A merge is in progress; resolve it before generating a commit.", IssueSeverityBlocking))
528: 	}
529: 	if repository.RebaseInProgress {
530: 		issues = append(issues, createIssue("rebase_in_progress", "A rebase is in progress; resolve it before generating a commit.", IssueSeverityBlocking))
531: 	}
532: 	if repository.CherryPickInProgress {
533: 		issues = append(issues, createIssue("cherry_pick_in_progress", "A cherry-pick is in progress; resolve it before generating a commit.", IssueSeverityBlocking))
534: 	}
535: 	if repository.IsDetachedHead {
536: 		issues = append(issues, createIssue("detached_head", "Repository is on a detached HEAD; committing here may be hard to find later.", IssueSeverityWarning))
537: 	}
538: 	if !repository.HasGitIdentity {
539: 		issues = append(issues, createIssue("git_identity_missing", "Git user.name and user.email must be configured before committing.", IssueSeverityBlocking))
540: 	}
541: 	for _, file := range files {
542: 		if file.Unstaged != nil {
543: 			issues = append(issues, createIssue("unstaged_changes_present", "Unstaged tracked changes are present in the working tree.", IssueSeverityWarning))
544: 			break
545: 		}
546: 	}
547: 	for _, file := range files {
548: 		if file.Untracked {
549: 			issues = append(issues, createIssue("untracked_files_present", "Untracked non-ignored files are present in the working tree.", IssueSeverityWarning))
550: 			break
551: 		}
552: 	}
553: 	if diff.Truncated {
554: 		issues = append(issues, createIssue("diff_truncated", "The inspected diff exceeded the configured size limit and was truncated.", IssueSeverityWarning))
555: 	}
556: 	return issues
557: }
