655: func workingTreeFileLooksBinary(path string) bool {
656: 	file, err := os.Open(path)
657: 	if err != nil {
658: 		return false
659: 	}
660: 	defer file.Close()
661: 
662: 	buffer := make([]byte, 8000)
663: 	n, err := file.Read(buffer)
664: 	if err != nil && n == 0 {
665: 		return false
666: 	}
667: 	return bytes.IndexByte(buffer[:n], 0) >= 0
668: }
