799: func mergeEnv(overrides map[string]string) []string {
800: 	if len(overrides) == 0 {
801: 		return os.Environ()
802: 	}
803: 	base := map[string]string{}
804: 	for _, pair := range os.Environ() {
805: 		parts := strings.SplitN(pair, "=", 2)
806: 		if len(parts) == 2 {
807: 			base[parts[0]] = parts[1]
808: 		}
809: 	}
810: 	for key, value := range overrides {
811: 		base[key] = value
812: 	}
813: 	result := make([]string, 0, len(base))
814: 	for key, value := range base {
815: 		result = append(result, key+"="+value)
816: 	}
817: 	return result
