723: func mergeFileStatus(files map[string]FileStatus, next FileStatus) {
724: 	existing, ok := files[next.Path]
725: 	if !ok {
726: 		files[next.Path] = next
727: 		return
728: 	}
729: 	if next.OriginalPath != nil {
730: 		existing.OriginalPath = next.OriginalPath
731: 	}
732: 	if next.Staged != nil {
733: 		existing.Staged = next.Staged
734: 	}
735: 	if next.Unstaged != nil {
736: 		existing.Unstaged = next.Unstaged
737: 	}
738: 	existing.Untracked = existing.Untracked || next.Untracked
739: 	existing.Binary = existing.Binary || next.Binary
740: 	files[next.Path] = existing
741: }
