773: func formatGitFailure(command, stderr, stdout string) string {
774: 	parts := make([]string, 0, 2)
775: 	if strings.TrimSpace(stderr) != "" {
776: 		parts = append(parts, strings.TrimSpace(stderr))
777: 	}
778: 	if strings.TrimSpace(stdout) != "" {
779: 		parts = append(parts, strings.TrimSpace(stdout))
780: 	}
781: 	if len(parts) == 0 {
782: 		return fmt.Sprintf("%s failed.", command)
783: 	}
784: 	return fmt.Sprintf("%s failed.\n%s", command, strings.Join(parts, "\n"))
785: }
