 36: func CreateToolCallProvider(options ToolCallProviderOptions) (runtimex.ToolCallProvider, error) {
 37: 	adapter, err := CreateToolProtocolAdapter(options.Config)
 38: 	if err != nil {
 39: 		return nil, err
 40: 	}
 41: 	if err := validateProviderConfig(options.Config, options.Config.Provider == config.ProviderOpenAICompatible); err != nil {
 42: 		return nil, err
 43: 	}
 44: 	return &httpToolCallProvider{
 45: 		cfg:          options.Config,
 46: 		adapter:      adapter,
 47: 		client:       resolveHTTPClient(options.Config),
