1294: func autoCommitExecutionFromToolCalls(calls []runtimex.ToolCallResult) (autoCommitExecution, bool) {
1295: 	failedCreateCallsBeforeFinal := 0
1296: 	for index := len(calls) - 1; index >= 0; index-- {
1297: 		call := calls[index]
1298: 		if call.Name != runtimex.ToolCreateCommits || !call.OK {
1299: 			continue
1300: 		}
1301: 		created, ok := call.Result.(runtimex.CreateCommitsResult)
1302: 		if !ok {
1303: 			continue
1304: 		}
1305: 		for _, prior := range calls[:index] {
1306: 			if prior.Name != runtimex.ToolCreateCommits || !prior.OK {
1307: 				continue
1308: 			}
1309: 			priorCreated, ok := prior.Result.(runtimex.CreateCommitsResult)
1310: 			if ok && priorCreated.Status == "commit_failed" {
1311: 				failedCreateCallsBeforeFinal++
1312: 			}
1313: 		}
1314: 		retryAttempt := created.RetryAttempt
1315: 		retryCount := created.RetryCount
1316: 		if created.Status == "committed" && failedCreateCallsBeforeFinal > 0 {
1317: 			retryAttempt = true
1318: 			retryCount = failedCreateCallsBeforeFinal
1319: 		}
1320: 		return autoCommitExecution{
1321: 			Plan:         autoPlanFromCreateCommitPlanResult(created.Plan),
1322: 			Results:      created.Results,
1323: 			Transaction:  created.Transaction,
1324: 			RetryAttempt: retryAttempt,
1325: 			RetryCount:   retryCount,
1326: 		}, true
1327: 	}
1328: 	return autoCommitExecution{}, false
1329: }
