1557: func runRoot(args []string, runtime Runtime) int {
1558: 	parsed, err := parseRootArgs(args)
1559: 	if err != nil {
1560: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
1561: 		return int(output.UsageError)
1562: 	}
1563: 
1564: 	flagOverrides, err := rootFlagOverrides(parsed)
1565: 	if err != nil {
1566: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
1567: 		return int(output.Error)
1568: 	}
1569: 
1570: 	resolvedConfig, configErr := config.ResolveEffectiveConfig(config.ResolveConfigOptions{CWD: runtime.CWD, Env: runtime.Env, FlagOverrides: flagOverrides, SecretStore: runtime.SecretStore})
1571: 	if !parsed.JSON && runtime.IsTTY && configErr == nil && needsOnboarding(resolvedConfig.Values) {
1572: 		if err := runFirstRunOnboarding(runtime, resolvedConfig.Values); err != nil {
1573: 			fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
1574: 			return int(output.Error)
1575: 		}
1576: 		resolvedConfig, configErr = config.ResolveEffectiveConfig(config.ResolveConfigOptions{CWD: runtime.CWD, Env: runtime.Env, FlagOverrides: flagOverrides, SecretStore: runtime.SecretStore})
1577: 	}
1578: 	preferenceSources := gitpkg.PreferenceExposure{}
1579: 	if configErr == nil {
1580: 		sourceSummary := config.SummarizeConfigSources(resolvedConfig)
1581: 		preferenceSources = gitpkg.PreferenceExposure{
1582: 			Provider:            string(sourceSummary.Provider),
