1588: 		}
1589: 	}
1590: 	scope, scopeErr := gitpkg.InspectCommitScope(gitpkg.CommitScopeOptions{
1591: 		CWD:               runtime.CWD,
1592: 		Env:               runtime.Env,
1593: 		StagedOnly:        parsed.Staged,
1594: 		IncludeUntracked:  !parsed.NoUntracked,
1595: 		DiffOnly:          parsed.DiffOnly,
1596: 		PreferenceSources: preferenceSources,
1597: 		Pathspecs:         parsed.Pathspecs,
1598: 	})
1599: 	if parsed.JSON {
1600: 		router := output.NewRouter(true, runtime.Stdout, runtime.Stderr)
1601: 		if scopeErr != nil {
1602: 			_ = router.WriteJSON(map[string]any{"schemaVersion": 1, "command": "cnm", "ok": false, "status": "scope_error", "scopeError": scopeErr.Error()})
1603: 			return int(output.Error)
1604: 		}
1605: 		_ = router.WriteJSON(map[string]any{"schemaVersion": 1, "command": "cnm", "ok": true, "status": "tui_preview", "scope": scope, "contextPolicy": scope.ContextPolicy, "aiExposure": scope.AIExposure})
1606: 		return int(output.Success)
1607: 	}
1608: 	if configErr != nil {
1609: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", configErr)
1610: 		return int(output.Error)
1611: 	}
1612: 	if scopeErr != nil {
1613: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", scopeErr)
1614: 		return int(output.Error)
1615: 	}
1616: 	modelInput := tui.ModelInput{
1617: 		Scope:        scope,
1618: 		PlanCommits:  interactiveCommitPlanner(runtime, parsed, resolvedConfig.Values, scope),
1619: 		DiffProvider: workingTreeDiffProvider(runtime, scope),
1620: 		FileReader:   repairFileReader(runtime),
1621: 	}
1622: 	if runtime.IsTTY {
1623: 		tuiRunner := runtime.TUIRunner
1624: 		if tuiRunner == nil {
1625: 			tuiRunner = tui.Run
1626: 		}
1627: 		result, err := tuiRunner(modelInput, tui.Runtime{Input: runtime.Stdin, Output: runtime.Stdout})
1628: 		if err != nil {
1629: 			fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
1630: 			return int(output.Error)
1631: 		}
1632: 		if !result.Accepted || result.Cancelled {
1633: 			fmt.Fprintln(runtime.Stderr, "Cancelled. No commit was created.")
1634: 			return int(output.UserCancel)
1635: 		}
1636: 		executionScope := filterScopeByPaths(scope, result.ScopeFiles)
1637: 		commitPlan, err := autoCommitPlanFromTUIPlan(result.CommitPlan, executionScope)
1638: 		if err != nil {
1639: 			fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
1640: 			return int(output.Error)
1641: 		}
1642: 		execution, err := executeCommitPlan(runtime, executionScope, autoArgs{NoVerify: parsed.NoVerify}, commitPlan)
1643: 		if err != nil {
1644: 			fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
1645: 			return int(output.Error)
1646: 		}
1647: 		commitResult := execution.lastResult()
1648: 		if commitResult.Git.ExitCode != 0 {
1649: 			fmt.Fprintln(runtime.Stderr, firstNonEmptyString(commitResult.Git.Stderr, commitResult.Git.Stdout, "git commit failed"))
1650: 			return int(output.Error)
1651: 		}
1652: 		fmt.Fprintf(runtime.Stdout, "Committed %s %s\n", commitResult.Hash, commitResult.Message)
1653: 		return int(output.Success)
1654: 	}
1655: 	modelInput.NoColor = true
1656: 	fmt.Fprint(runtime.Stdout, tui.NewModel(modelInput).View())
1657: 	return int(output.Success)
1658: }
