1688: func parseRootArgs(args []string) (rootArgs, error) {
1689: 	parsed := rootArgs{}
1690: 	for index := 0; index < len(args); index++ {
1691: 		arg := args[index]
1692: 		if arg == "--" {
1693: 			parsed.Pathspecs = append(parsed.Pathspecs, args[index+1:]...)
1694: 			return parsed, nil
1695: 		}
1696: 		switch arg {
1697: 		case "--json":
1698: 			parsed.JSON = true
1699: 		case "--staged":
1700: 			parsed.Staged = true
1701: 		case "--no-untracked":
1702: 			parsed.NoUntracked = true
1703: 		case "--diff-only":
1704: 			parsed.DiffOnly = true
1705: 		case "--no-verify":
1706: 			parsed.NoVerify = true
1707: 		case "--provider":
1708: 			value, next, err := requireNextArg(args, index)
1709: 			if err != nil {
1710: 				return parsed, err
1711: 			}
1712: 			parsed.Provider = value
1713: 			index = next
1714: 		case "--model":
1715: 			value, next, err := requireNextArg(args, index)
1716: 			if err != nil {
1717: 				return parsed, err
1718: 			}
1719: 			parsed.Model = value
1720: 			index = next
1721: 		case "--base-url":
1722: 			value, next, err := requireNextArg(args, index)
1723: 			if err != nil {
1724: 				return parsed, err
1725: 			}
1726: 			parsed.BaseURL = value
1727: 			index = next
1728: 		case "--prompt-style":
1729: 			value, next, err := requireNextArg(args, index)
1730: 			if err != nil {
1731: 				return parsed, err
1732: 			}
1733: 			parsed.PromptStyle = value
1734: 			index = next
1735: 		case "--message-language":
1736: 			value, next, err := requireNextArg(args, index)
1737: 			if err != nil {
1738: 				return parsed, err
1739: 			}
1740: 			parsed.MessageLanguage = value
1741: 			index = next
1742: 		case "--standing-instruction":
1743: 			value, next, err := requireNextArg(args, index)
1744: 			if err != nil {
1745: 				return parsed, err
1746: 			}
1747: 			parsed.StandingInstruction = value
1748: 			index = next
1749: 		default:
1750: 			if strings.HasPrefix(arg, "-") {
1751: 				return parsed, fmt.Errorf("unknown option %q", arg)
1752: 			}
1753: 			return parsed, fmt.Errorf("unknown command '%s'", arg)
1754: 		}
1755: 	}
1756: 	return parsed, nil
1757: }
