1759: func requireNextArg(args []string, index int) (string, int, error) {
1760: 	if index+1 >= len(args) {
1761: 		return "", index, fmt.Errorf("missing value for %s", args[index])
1762: 	}
1763: 	return args[index+1], index + 1, nil
1764: }
