1892: func runFirstRunOnboardingTUI(runtime Runtime, current config.EffectiveConfig) error {
1893: 	input := tui.OnboardingInput{
1894: 		CurrentProvider: current.Provider,
1895: 		CurrentModel:    current.Model,
1896: 		CurrentStyle:    current.PromptStyle,
