1901: 	}
1902: 	if current.StandingInstruction != nil {
1903: 		input.CurrentStanding = *current.StandingInstruction
1904: 	}
1905: 	result, err := runtime.OnboardingRunner(input, tui.Runtime{Input: runtime.Stdin, Output: runtime.Stdout})
1906: 	if err != nil {
1907: 		return err
1908: 	}
1909: 	if result.Cancelled {
1910: 		return fmt.Errorf("onboarding cancelled")
1911: 	}
1912: 	provider := result.Provider
1913: 	if provider == "" {
1914: 		provider = config.DefaultProvider
1915: 	}
1916: 	model := strings.TrimSpace(result.Model)
1917: 	if model == "" {
1918: 		model = config.GetDefaultModel(provider)
1919: 	}
1920: 	apiKey := strings.TrimSpace(result.APIKey)
1921: 	if apiKey == "" {
1922: 		return fmt.Errorf("API key is required")
1923: 	}
1924: 	save, err := config.SaveAPIKeyToSecretStore(provider, apiKey, runtime.SecretStore)
1925: 	if err != nil {
1926: 		return fmt.Errorf("%v Use `cnm init --plaintext-api-key` to store this key in user config instead.", err)
1927: 	}
1928: 	if !save.Stored {
1929: 		message := "Secret Store is not available; use `cnm init --plaintext-api-key` to store this key in user config instead."
1930: 		if save.Warning != nil {
1931: 			message = *save.Warning
1932: 		}
1933: 		return fmt.Errorf("%s", message)
1934: 	}
1935: 	var baseURL *string
1936: 	if provider == config.ProviderOpenAICompatible || strings.TrimSpace(result.BaseURL) != "" {
1937: 		baseURL = optionalStringPointer(result.BaseURL)
1938: 	}
1939: 	style := result.PromptStyle
1940: 	if style == "" {
1941: 		style = config.DefaultPromptStyle
1942: 	}
1943: 	language := result.MessageLanguage
1944: 	if language == "" {
1945: 		language = config.DefaultMessageLanguage
1946: 	}
1947: 	patch := config.ConfigValues{
1948: 		Provider:            &provider,
1949: 		Model:               &model,
1950: 		BaseURL:             baseURL,
1951: 		PromptStyle:         &style,
1952: 		MessageLanguage:     &language,
1953: 		StandingInstruction: optionalStringPointer(result.StandingInstruction),
1954: 	}
1955: 	if _, err := config.WriteUserConfigPatch(patch, config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env}); err != nil {
1956: 		return err
1957: 	}
1958: 	_, err = fmt.Fprintln(runtime.Stdout, "Onboarding complete.")
1959: 	return err
1960: }
