1304: 		}
1305: 		for _, prior := range calls[:index] {
1306: 			if prior.Name != runtimex.ToolCreateCommits || !prior.OK {
1307: 				continue
1308: 			}
1309: 			priorCreated, ok := prior.Result.(runtimex.CreateCommitsResult)
1310: 			if ok && priorCreated.Status == "commit_failed" {
