1380: func autoCommitPlanFromTUIPlan(plan tui.CommitPlanView, scope gitpkg.CommitScope) (autoCommitPlan, error) {
1381: 	if len(plan.Commits) == 0 {
1382: 		return autoCommitPlan{}, fmt.Errorf("commit plan is required")
1383: 	}
1384: 	filesByPath := map[string]gitpkg.FileStatus{}
1385: 	for _, file := range scope.Files {
1386: 		filesByPath[file.Path] = file
1387: 	}
1388: 	commits := make([]autoPlannedCommit, 0, len(plan.Commits))
1389: 	used := map[string]bool{}
1390: 	for _, commit := range plan.Commits {
1391: 		if strings.TrimSpace(commit.Message) == "" {
1392: 			return autoCommitPlan{}, fmt.Errorf("commit message is required")
1393: 		}
1394: 		files := make([]gitpkg.FileStatus, 0, len(commit.Files))
1395: 		for _, path := range commit.Files {
1396: 			file, ok := filesByPath[path]
1397: 			if !ok {
1398: 				return autoCommitPlan{}, fmt.Errorf("commit plan references file outside Commit Scope: %s", path)
1399: 			}
1400: 			if used[path] {
1401: 				return autoCommitPlan{}, fmt.Errorf("commit plan assigns file more than once: %s", path)
1402: 			}
1403: 			used[path] = true
1404: 			files = append(files, file)
1405: 		}
1406: 		if len(files) == 0 {
1407: 			return autoCommitPlan{}, fmt.Errorf("commit plan contains an empty commit")
1408: 		}
1409: 		commits = append(commits, autoPlannedCommit{Message: commit.Message, Files: files})
1410: 	}
1411: 	return autoCommitPlan{Kind: emptyDefaultString(plan.Kind, "single"), Commits: commits}, nil
1412: }
