1418: 	selected := map[string]bool{}
1419: 	for _, path := range paths {
1420: 		selected[path] = true
1421: 	}
1422: 	filtered := scope
1423: 	filtered.Files = make([]gitpkg.FileStatus, 0, len(scope.Files))
1424: 	for _, file := range scope.Files {
1425: 		if selected[file.Path] {
1426: 			filtered.Files = append(filtered.Files, file)
1427: 		}
1428: 	}
1429: 	filtered.HasSelectedChanges = len(filtered.Files) > 0
1430: 	return filtered
