1660: func interactiveCommitPlanner(runtime Runtime, parsed rootArgs, resolvedConfig config.EffectiveConfig, initialScope gitpkg.CommitScope) tui.PlanCommitsFunc {
1661: 	return func(input tui.PlanCommitsInput) (tui.CommitPlanView, error) {
1662: 		executionScope := filterScopeByPaths(input.Scope, input.ScopeFiles)
1663: 		executionScope.StagedOnly = initialScope.StagedOnly
1664: 		executionScope.IncludesUntracked = initialScope.IncludesUntracked
1665: 		execution, err := executeAutoCommit(runtime, executionScope, autoArgs{DryRun: true, Staged: parsed.Staged, NoUntracked: parsed.NoUntracked, DiffOnly: parsed.DiffOnly, NoVerify: parsed.NoVerify, Pathspecs: parsed.Pathspecs}, resolvedConfig)
1666: 		if err != nil {
1667: 			return tui.CommitPlanView{}, err
1668: 		}
1669: 		return tuiCommitPlanFromAutoPlan(execution.Plan), nil
1670: 	}
1671: }
