1701: 		case "--no-untracked":
1702: 			parsed.NoUntracked = true
1703: 		case "--diff-only":
1704: 			parsed.DiffOnly = true
1705: 		case "--no-verify":
1706: 			parsed.NoVerify = true
1707: 		case "--provider":
