1823: func runFirstRunOnboarding(runtime Runtime, current config.EffectiveConfig) error {
1824: 	if runtime.IsTTY && runtime.OnboardingRunner != nil {
1825: 		return runFirstRunOnboardingTUI(runtime, current)
1826: 	}
1827: 	prompter := interactive.NewPrompter(runtime.Stdin, runtime.Stdout)
1828: 	if _, err := fmt.Fprintln(runtime.Stdout, "Onboarding"); err != nil {
1829: 		return err
1830: 	}
1831: 	provider, err := askOnboardingProvider(prompter)
1832: 	if err != nil {
1833: 		return err
1834: 	}
1835: 	model, err := askOnboardingText(prompter, "Model", config.GetDefaultModel(provider), true)
1836: 	if err != nil {
1837: 		return err
1838: 	}
1839: 	var baseURL *string
1840: 	if provider == config.ProviderOpenAICompatible {
1841: 		value, err := askOnboardingText(prompter, "Base URL", "", true)
1842: 		if err != nil {
1843: 			return err
1844: 		}
1845: 		baseURL = &value
1846: 	} else {
1847: 		baseURL = current.BaseURL
1848: 	}
1849: 	promptStyle, err := askOnboardingPromptStyle(prompter)
1850: 	if err != nil {
1851: 		return err
1852: 	}
1853: 	messageLanguage, err := askOnboardingMessageLanguage(prompter)
1854: 	if err != nil {
1855: 		return err
1856: 	}
1857: 	standingInstruction, err := askOnboardingText(prompter, "Standing Instruction", stringPointerValue(current.StandingInstruction), false)
1858: 	if err != nil {
1859: 		return err
1860: 	}
1861: 	apiKey, err := askOnboardingText(prompter, "API key", "", true)
1862: 	if err != nil {
1863: 		return err
1864: 	}
1865: 
1866: 	save, err := config.SaveAPIKeyToSecretStore(provider, apiKey, runtime.SecretStore)
1867: 	if err != nil {
1868: 		return fmt.Errorf("%v Use `cnm init --plaintext-api-key` to store this key in user config instead.", err)
1869: 	}
1870: 	if !save.Stored {
1871: 		message := "Secret Store is not available; use `cnm init --plaintext-api-key` to store this key in user config instead."
1872: 		if save.Warning != nil {
1873: 			message = *save.Warning
1874: 		}
1875: 		return fmt.Errorf("%s", message)
1876: 	}
1877: 	patch := config.ConfigValues{
1878: 		Provider:            &provider,
1879: 		Model:               &model,
1880: 		BaseURL:             baseURL,
1881: 		PromptStyle:         &promptStyle,
1882: 		MessageLanguage:     &messageLanguage,
1883: 		StandingInstruction: optionalStringPointer(standingInstruction),
1884: 	}
1885: 	if _, err := config.WriteUserConfigPatch(patch, config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env}); err != nil {
1886: 		return err
1887: 	}
1888: 	_, err = fmt.Fprintln(runtime.Stdout, "Onboarding complete.")
1889: 	return err
1890: }
