2064: func resolveCommand(args []string) (string, int) {
2065: 	for index := 0; index < len(args); index++ {
2066: 		token := args[index]
2067: 		if token == "--" {
2068: 			return "", -1
2069: 		}
2070: 		if isRootFlagWithValue(token) {
2071: 			index++
2072: 			continue
2073: 		}
2074: 		if strings.HasPrefix(token, "-") {
2075: 			continue
2076: 		}
2077: 		if token == "init" || token == "config" || token == "doctor" || token == "split" || token == "help" {
2078: 			return token, index
2079: 		}
2080: 		return token, index
2081: 	}
2082: 	return "", -1
2083: }
