320: func (m *Model) toggleCurrentScopeFile() {
321: 	if len(m.Scope.Files) == 0 || m.ScopeCursor < 0 || m.ScopeCursor >= len(m.Scope.Files) {
322: 		return
323: 	}
324: 	if m.ScopeIncluded == nil {
325: 		m.ScopeIncluded = map[string]bool{}
326: 		for _, file := range m.Scope.Files {
327: 			m.ScopeIncluded[file.Path] = true
328: 		}
329: 	}
330: 	path := m.Scope.Files[m.ScopeCursor].Path
331: 	m.ScopeIncluded[path] = !m.scopeFileIncluded(path)
332: 	m.CommitPlan = filterCommitPlanByIncluded(m.CommitPlan, m.ScopeIncluded)
333: }
