373: func filterCommitPlanByIncluded(plan CommitPlanView, included map[string]bool) CommitPlanView {
374: 	if included == nil || len(plan.Commits) == 0 {
375: 		return plan
376: 	}
377: 	next := CommitPlanView{Kind: plan.Kind}
378: 	for _, commit := range plan.Commits {
379: 		files := make([]string, 0, len(commit.Files))
380: 		for _, file := range commit.Files {
381: 			if selected, ok := included[file]; !ok || selected {
382: 				files = append(files, file)
383: 			}
384: 		}
385: 		if len(files) == 0 {
386: 			continue
387: 		}
388: 		next.Commits = append(next.Commits, CommitView{Message: commit.Message, Files: files})
389: 	}
390: 	if len(next.Commits) == 1 && next.Kind == "file_split" {
391: 		next.Kind = "single"
392: 	}
393: 	return next
394: }
