423: func (m Model) previewContent() string {
424: 	if m.RepairContext != nil {
425: 		return m.repairPreview()
426: 	}
427: 	switch m.Screen {
428: 	case ScreenScopeReview, ScreenAgentInstruction:
429: 		return m.diffPreview()
430: 	case ScreenAIActivity:
431: 		return m.theme.Muted().Render("Planning commits with local Domain Tools…")
432: 	case ScreenMessageReview, ScreenMessageEdit:
433: 		return m.commitPlanPreview()
434: 	}
435: 	return ""
436: }
