 18: const (
 19: 	ScreenScopeReview      Screen = "scope_review"
 20: 	ScreenAgentInstruction Screen = "agent_instruction"
 21: 	ScreenAIActivity       Screen = "ai_activity"
 22: 	ScreenMessageReview    Screen = "message_review"
