146: func (m Model) Init() tea.Cmd {
147: 	return m.spinner.Tick
148: }
149: 
150: func (m Model) Result() Result {
151: 	return Result{
152: 		Accepted:   m.Accepted,
153: 		Cancelled:  m.Cancelled,
154: 		CommitPlan: m.CommitPlan,
155: 		ScopeFiles: m.selectedScopeFilePaths(),
156: 	}
157: }
158: 
159: func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
160: 	switch msg := msg.(type) {
161: 	case tea.KeyMsg:
162: 		return m.handleKey(msg)
163: 	case AIActivityDoneMsg:
164: 		if msg.Err != nil {
165: 			m.AIActivityError = msg.Err.Error()
166: 			m.Screen = ScreenAgentInstruction
167: 			return m, nil
168: 		}
169: 		m.AIActivityError = ""
170: 		m.CommitPlan = msg.Plan
171: 		m.Screen = ScreenMessageReview
172: 		m.refreshPreview()
173: 		return m, nil
174: 	case tea.WindowSizeMsg:
175: 		if msg.Width > 0 {
176: 			m.Width = msg.Width
177: 		}
178: 		if msg.Height > 0 {
179: 			m.Height = msg.Height
180: 		}
181: 		m.refreshPreview()
182: 		return m, nil
183: 	case spinner.TickMsg:
184: 		var cmd tea.Cmd
185: 		m.spinner, cmd = m.spinner.Update(msg)
186: 		return m, cmd
187: 	}
188: 	return m, nil
189: }
190: 
191: func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
192: 	switch msg.Type {
193: 	case tea.KeyCtrlC:
194: 		m.Cancelled = true
195: 		return m, tea.Quit
196: 	case tea.KeyRunes:
197: 		s := msg.String()
198: 		if s == "q" && m.Screen != ScreenAgentInstruction && m.Screen != ScreenMessageEdit {
199: 			m.Cancelled = true
200: 			return m, tea.Quit
201: 		}
202: 		if m.Screen == ScreenScopeReview {
203: 			switch s {
204: 			case "j":
205: 				m.moveScopeCursor(1)
206: 				return m, nil
207: 			case "k":
208: 				m.moveScopeCursor(-1)
209: 				return m, nil
210: 			case "a":
211: 				m.toggleAllScope(true)
212: 				return m, nil
213: 			case "n":
214: 				m.toggleAllScope(false)
215: 				return m, nil
216: 			}
217: 		}
218: 		if m.Screen == ScreenMessageReview && s == "e" && len(m.CommitPlan.Commits) > 0 {
219: 			m.MessageDraft = m.CommitPlan.Commits[0].Message
220: 			m.Screen = ScreenMessageEdit
221: 			return m, nil
222: 		}
223: 		if m.Screen == ScreenAgentInstruction {
224: 			m.AgentInstruction += s
225: 		}
226: 		if m.Screen == ScreenMessageEdit {
227: 			m.MessageDraft += s
228: 		}
229: 	case tea.KeySpace:
230: 		if m.Screen == ScreenScopeReview {
231: 			m.toggleCurrentScopeFile()
232: 			return m, nil
233: 		}
234: 		if m.Screen == ScreenAgentInstruction {
235: 			m.AgentInstruction += " "
236: 		}
237: 		if m.Screen == ScreenMessageEdit {
238: 			m.MessageDraft += " "
239: 		}
240: 	case tea.KeyEnter:
241: 		switch m.Screen {
242: 		case ScreenRepairReview:
243: 			m.Accepted = true
244: 			return m, tea.Quit
245: 		case ScreenScopeReview:
246: 			if m.selectedScopeFileCount() == 0 {
247: 				return m, nil
248: 			}
249: 			m.CommitPlan = filterCommitPlanByIncluded(m.CommitPlan, m.ScopeIncluded)
250: 			m.Screen = ScreenAgentInstruction
251: 			m.refreshPreview()
252: 		case ScreenAgentInstruction:
253: 			m.Screen = ScreenAIActivity
254: 			return m, planAIActivity(m.PlanCommits, PlanCommitsInput{Scope: m.Scope, ScopeFiles: m.selectedScopeFilePaths(), AgentInstruction: m.AgentInstruction}, m.CommitPlan)
255: 		case ScreenMessageEdit:
256: 			if len(m.CommitPlan.Commits) > 0 && strings.TrimSpace(m.MessageDraft) != "" {
257: 				m.CommitPlan.Commits[0].Message = strings.TrimSpace(m.MessageDraft)
258: 			}
259: 			m.Screen = ScreenMessageReview
260: 			m.refreshPreview()
261: 		case ScreenMessageReview:
262: 			m.Accepted = true
263: 			return m, tea.Quit
264: 		}
265: 	case tea.KeyBackspace, tea.KeyDelete:
266: 		if m.Screen == ScreenAgentInstruction && len(m.AgentInstruction) > 0 {
267: 			runes := []rune(m.AgentInstruction)
268: 			m.AgentInstruction = string(runes[:len(runes)-1])
269: 		}
270: 		if m.Screen == ScreenMessageEdit && len(m.MessageDraft) > 0 {
271: 			runes := []rune(m.MessageDraft)
272: 			m.MessageDraft = string(runes[:len(runes)-1])
273: 		}
274: 	case tea.KeyUp:
275: 		if m.Screen == ScreenScopeReview {
276: 			m.moveScopeCursor(-1)
277: 			return m, nil
278: 		}
279: 		if m.previewSet {
280: 			m.preview.LineUp(1)
281: 			return m, nil
282: 		}
283: 	case tea.KeyDown:
284: 		if m.Screen == ScreenScopeReview {
285: 			m.moveScopeCursor(1)
286: 			return m, nil
287: 		}
288: 		if m.previewSet {
289: 			m.preview.LineDown(1)
290: 			return m, nil
291: 		}
292: 	case tea.KeyPgUp:
293: 		if m.previewSet {
294: 			m.preview.HalfViewUp()
295: 		}
296: 	case tea.KeyPgDown:
297: 		if m.previewSet {
298: 			m.preview.HalfViewDown()
299: 		}
300: 	}
301: 	return m, nil
302: }
303: 
304: func (m *Model) moveScopeCursor(delta int) {
305: 	if len(m.Scope.Files) == 0 {
306: 		m.ScopeCursor = 0
307: 		return
308: 	}
309: 	next := m.ScopeCursor + delta
310: 	if next < 0 {
311: 		next = 0
312: 	}
313: 	if next >= len(m.Scope.Files) {
314: 		next = len(m.Scope.Files) - 1
315: 	}
316: 	m.ScopeCursor = next
317: 	m.refreshPreview()
318: }
319: 
320: func (m *Model) toggleCurrentScopeFile() {
321: 	if len(m.Scope.Files) == 0 || m.ScopeCursor < 0 || m.ScopeCursor >= len(m.Scope.Files) {
322: 		return
323: 	}
324: 	if m.ScopeIncluded == nil {
325: 		m.ScopeIncluded = map[string]bool{}
326: 		for _, file := range m.Scope.Files {
327: 			m.ScopeIncluded[file.Path] = true
328: 		}
329: 	}
330: 	path := m.Scope.Files[m.ScopeCursor].Path
331: 	m.ScopeIncluded[path] = !m.scopeFileIncluded(path)
332: 	m.CommitPlan = filterCommitPlanByIncluded(m.CommitPlan, m.ScopeIncluded)
333: }
334: 
335: func (m *Model) toggleAllScope(include bool) {
336: 	if m.ScopeIncluded == nil {
337: 		m.ScopeIncluded = map[string]bool{}
338: 	}
339: 	for _, file := range m.Scope.Files {
340: 		m.ScopeIncluded[file.Path] = include
341: 	}
342: 	m.CommitPlan = filterCommitPlanByIncluded(m.CommitPlan, m.ScopeIncluded)
343: }
344: 
345: func (m Model) scopeFileIncluded(path string) bool {
346: 	if m.ScopeIncluded == nil {
347: 		return true
348: 	}
349: 	included, ok := m.ScopeIncluded[path]
350: 	return !ok || included
351: }
352: 
353: func (m Model) selectedScopeFileCount() int {
354: 	count := 0
355: 	for _, file := range m.Scope.Files {
356: 		if m.scopeFileIncluded(file.Path) {
357: 			count++
358: 		}
359: 	}
360: 	return count
361: }
362: 
363: func (m Model) selectedScopeFilePaths() []string {
364: 	paths := make([]string, 0)
365: 	for _, file := range m.Scope.Files {
366: 		if m.scopeFileIncluded(file.Path) {
367: 			paths = append(paths, file.Path)
368: 		}
369: 	}
370: 	return paths
371: }
372: 
373: func filterCommitPlanByIncluded(plan CommitPlanView, included map[string]bool) CommitPlanView {
374: 	if included == nil || len(plan.Commits) == 0 {
375: 		return plan
376: 	}
377: 	next := CommitPlanView{Kind: plan.Kind}
378: 	for _, commit := range plan.Commits {
379: 		files := make([]string, 0, len(commit.Files))
380: 		for _, file := range commit.Files {
381: 			if selected, ok := included[file]; !ok || selected {
382: 				files = append(files, file)
383: 			}
384: 		}
385: 		if len(files) == 0 {
386: 			continue
387: 		}
388: 		next.Commits = append(next.Commits, CommitView{Message: commit.Message, Files: files})
389: 	}
390: 	if len(next.Commits) == 1 && next.Kind == "file_split" {
391: 		next.Kind = "single"
392: 	}
393: 	return next
394: }
395: 
396: func planAIActivity(planner PlanCommitsFunc, input PlanCommitsInput, fallback CommitPlanView) tea.Cmd {
397: 	return func() tea.Msg {
398: 		if planner == nil {
399: 			return AIActivityDoneMsg{Plan: fallback}
400: 		}
401: 		plan, err := planner(input)
402: 		return AIActivityDoneMsg{Plan: plan, Err: err}
403: 	}
404: }
405: 
406: func (m *Model) refreshPreview() {
407: 	previewWidth, previewHeight := m.previewDims()
408: 	m.preview.Width = previewWidth
409: 	m.preview.Height = previewHeight
410: 	m.preview.SetContent(m.previewContent())
411: 	m.previewSet = true
412: }
413: 
414: func (m Model) previewDims() (int, int) {
415: 	if !m.useTwoColumn() {
416: 		return m.contentWidth(), m.bodyHeight() / 2
417: 	}
418: 	left, right := m.columnWidths()
419: 	_ = left
420: 	return right - 4, m.bodyHeight() - 4
421: }
422: 
423: func (m Model) previewContent() string {
424: 	if m.RepairContext != nil {
425: 		return m.repairPreview()
426: 	}
427: 	switch m.Screen {
428: 	case ScreenScopeReview, ScreenAgentInstruction:
429: 		return m.diffPreview()
430: 	case ScreenAIActivity:
431: 		return m.theme.Muted().Render("Planning commits with local Domain Tools…")
432: 	case ScreenMessageReview, ScreenMessageEdit:
433: 		return m.commitPlanPreview()
434: 	}
435: 	return ""
436: }
437: 
438: func (m Model) diffPreview() string {
439: 	if len(m.Scope.Files) == 0 {
440: 		return m.theme.Muted().Render("No selected changes")
441: 	}
442: 	if m.ScopeCursor < 0 || m.ScopeCursor >= len(m.Scope.Files) {
443: 		return ""
444: 	}
445: 	file := m.Scope.Files[m.ScopeCursor]
446: 	header := m.theme.Section().Render(file.Path)
447: 	if m.DiffProvider == nil {
448: 		statusLine := m.fileStatus(file)
449: 		return joinNonEmpty([]string{header, m.theme.Subtle().Render(statusLine), m.theme.Muted().Render("(no diff provider attached)")})
450: 	}
451: 	content, err := m.DiffProvider(file.Path)
452: 	if err != nil {
453: 		return joinNonEmpty([]string{header, m.theme.Error().Render("diff error: " + err.Error())})
454: 	}
455: 	if strings.TrimSpace(content) == "" {
456: 		statusLine := m.fileStatus(file)
457: 		return joinNonEmpty([]string{header, m.theme.Subtle().Render(statusLine), m.theme.Muted().Render("(no diff yet)")})
458: 	}
459: 	return joinNonEmpty([]string{header, m.colorizeDiff(content)})
460: }
461: 
462: func (m Model) repairPreview() string {
463: 	if m.RepairContext == nil {
464: 		return ""
465: 	}
466: 	lines := []string{m.theme.Section().Render("Conflict context")}
467: 	if strings.TrimSpace(m.RepairContext.Reason) != "" {
468: 		lines = append(lines, m.theme.Text().Render(m.RepairContext.Reason))
469: 	}
470: 	if len(m.RepairContext.EligibleFiles) == 0 {
471: 		return joinNonEmpty(lines)
472: 	}
473: 	if m.FileReader == nil {
474: 		lines = append(lines, m.theme.Muted().Render("Eligible files:"))
475: 		for _, file := range m.RepairContext.EligibleFiles {
476: 			lines = append(lines, "  "+file)
477: 		}
478: 		return joinNonEmpty(lines)
479: 	}
480: 	for _, path := range m.RepairContext.EligibleFiles {
481: 		lines = append(lines, m.theme.Section().Render(path))
482: 		body, err := m.FileReader(path)
483: 		if err != nil {
484: 			lines = append(lines, m.theme.Error().Render("read error: "+err.Error()))
485: 			continue
486: 		}
487: 		lines = append(lines, m.colorizeConflict(body))
488: 	}
489: 	return joinNonEmpty(lines)
490: }
491: 
492: func (m Model) commitPlanPreview() string {
493: 	if len(m.CommitPlan.Commits) == 0 {
494: 		return m.theme.Muted().Render("No plan yet")
495: 	}
496: 	out := []string{m.theme.Section().Render(fmt.Sprintf("mode %s  %d commit(s)", emptyDefault(m.CommitPlan.Kind, "single"), len(m.CommitPlan.Commits)))}
497: 	for index, commit := range m.CommitPlan.Commits {
498: 		out = append(out, m.theme.Accent().Render(fmt.Sprintf("%d. %s", index+1, commit.Message)))
499: 		for _, file := range commit.Files {
500: 			out = append(out, m.theme.Subtle().Render("    "+file))
501: 		}
502: 	}
503: 	return strings.Join(out, "\n")
504: }
505: 
506: func (m Model) colorizeDiff(diff string) string {
507: 	lines := strings.Split(diff, "\n")
508: 	out := make([]string, 0, len(lines))
509: 	for _, line := range lines {
510: 		switch {
511: 		case strings.HasPrefix(line, "+++") || strings.HasPrefix(line, "---") || strings.HasPrefix(line, "@@") || strings.HasPrefix(line, "diff "):
512: 			out = append(out, m.theme.DiffMeta().Render(line))
513: 		case strings.HasPrefix(line, "+"):
514: 			out = append(out, m.theme.DiffAdd().Render(line))
515: 		case strings.HasPrefix(line, "-"):
516: 			out = append(out, m.theme.DiffDel().Render(line))
517: 		default:
518: 			out = append(out, m.theme.Text().Render(line))
519: 		}
520: 	}
521: 	return strings.Join(out, "\n")
522: }
523: 
524: func (m Model) colorizeConflict(body string) string {
525: 	lines := strings.Split(body, "\n")
526: 	out := make([]string, 0, len(lines))
527: 	for _, line := range lines {
528: 		switch {
529: 		case strings.HasPrefix(line, "<<<<<<<") || strings.HasPrefix(line, ">>>>>>>"):
530: 			out = append(out, m.theme.DiffMeta().Render(line))
531: 		case strings.HasPrefix(line, "======="):
532: 			out = append(out, m.theme.DiffMeta().Render(line))
533: 		default:
534: 			out = append(out, m.theme.Text().Render(line))
535: 		}
536: 	}
537: 	return strings.Join(out, "\n")
538: }
