 618: func composeErrorDetail(hint, raw string) string {
 619: 	parts := []string{}
 620: 	if hint != "" {
 621: 		parts = append(parts, hint)
 622: 	}
 623: 	if raw != "" {
 624: 		parts = append(parts, "Raw error: "+raw)
 625: 	}
 626: 	return strings.Join(parts, "\n\n")
 627: }
