 638: func matchesHTTPStatus(raw string, codes ...int) bool {
 639: 	for _, code := range codes {
 640: 		c := strconv.Itoa(code)
 641: 		patterns := []string{
 642: 			"http " + c + ":",
 643: 			"http " + c + " ",
 644: 			"status " + c,
 645: 			"status: " + c,
 646: 			"status:" + c,
 647: 			"\"status\":" + c,
 648: 			"code " + c,
 649: 			"code: " + c,
 650: 			"\"code\":" + c,
 651: 			" " + c + " ",
 652: 			"(" + c + ")",
 653: 			"[" + c + "]",
 654: 		}
 655: 		lower := strings.ToLower(raw)
 656: 		for _, p := range patterns {
 657: 			if strings.Contains(lower, p) {
 658: 				return true
 659: 			}
 660: 		}
 661: 	}
 662: 	return false
 663: }
