 665: func extractParseDetail(raw string) string {
 666: 	idx := strings.Index(raw, "response body:")
 667: 	if idx < 0 {
 668: 		return raw
 669: 	}
 670: 	body := strings.TrimSpace(raw[idx+len("response body:"):])
 671: 	body = strings.TrimSuffix(body, ")")
 672: 	body = strings.TrimSpace(body)
 673: 	if body == "" {
 674: 		return raw
 675: 	}
 676: 	return body
 677: }
