 706: func (m Model) fileStatus(file gitpkg.FileStatus) string {
 707: 	parts := []string{}
 708: 	if file.Untracked {
 709: 		parts = append(parts, "untracked")
 710: 	}
 711: 	if file.Staged != nil {
 712: 		parts = append(parts, "staged:"+string(*file.Staged))
 713: 	}
 714: 	if file.Unstaged != nil {
 715: 		parts = append(parts, "unstaged:"+string(*file.Unstaged))
 716: 	}
 717: 	if isFileConflict(file) {
 718: 		parts = append(parts, "conflict")
 719: 	}
 720: 	if file.Binary {
 721: 		parts = append(parts, "binary")
 722: 	}
 723: 	if len(parts) == 0 {
 724: 		return "modified"
 725: 	}
 726: 	return strings.Join(parts, " ")
 727: }
