 810: func (m Model) renderBodySingleColumn() string {
 811: 	width := m.contentWidth()
 812: 	available := m.bodyHeight()
 813: 	parts := []string{}
 814: 	used := 0
 815: 	tryAdd := func(block string) bool {
 816: 		if block == "" {
 817: 			return false
 818: 		}
 819: 		height := strings.Count(block, "\n") + 1
 820: 		if used+height > available {
 821: 			return false
 822: 		}
 823: 		parts = append(parts, block)
 824: 		used += height
 825: 		return true
 826: 	}
 827: 	exposure := m.renderExposureLine()
 828: 	exposureHeight := 0
 829: 	if exposure != "" {
 830: 		exposureHeight = 1
 831: 	}
 832: 	scopeRows := m.singleColumnScopeRows(width)
 833: 	scopeBudget := len(scopeRows) + 2
 834: 	maxScope := available / 3
 835: 	if maxScope < 4 {
 836: 		maxScope = 4
 837: 	}
 838: 	if scopeBudget > maxScope {
 839: 		scopeBudget = maxScope
 840: 	}
 841: 	if scopeBudget < 4 {
 842: 		scopeBudget = 4
 843: 	}
 844: 	tryAdd(m.renderScopePanelFixedHeight(width, scopeBudget, scopeRows))
 845: 	planBlock := m.renderCommitPlanPanel(width)
 846: 	planHeight := strings.Count(planBlock, "\n") + 1
 847: 	reservedForPlan := 0
 848: 	if len(m.CommitPlan.Commits) > 0 && planHeight <= 8 {
 849: 		reservedForPlan = planHeight
 850: 	}
 851: 	previewBudget := available - used - exposureHeight - reservedForPlan - 1
 852: 	if previewBudget < 5 {
 853: 		previewBudget = 5
 854: 	}
 855: 	previewTitle, previewBody := m.activePreviewForSingleColumn()
 856: 	tryAdd(m.renderViewportPanel(width, previewBudget, previewTitle, previewBody))
 857: 	if reservedForPlan > 0 {
 858: 		tryAdd(planBlock)
 859: 	}
 860: 	tryAdd(exposure)
 861: 	return strings.Join(parts, "\n")
 862: }
