 867: 		innerWidth = 8
 868: 	}
 869: 	heading := fmt.Sprintf("Commit Scope  %d files  %d selected", len(m.Scope.Files), m.selectedScopeFileCount())
 870: 	if m.RepairContext == nil && m.Screen == ScreenScopeReview {
 871: 		heading = m.theme.Section().Render(heading)
 872: 	} else {
 873: 		heading = m.theme.Subtle().Render(heading)
 874: 	}
 875: 	rows := []string{fitLine(heading, innerWidth)}
 876: 	if len(m.Scope.Files) == 0 {
 877: 		rows = append(rows, fitLine(m.theme.Muted().Render("No selected changes"), innerWidth))
 878: 		return rows
 879: 	}
 880: 	visible, start, end := m.visibleFiles()
 881: 	for index, file := range visible {
 882: 		active := start+index == m.ScopeCursor && m.Screen == ScreenScopeReview && m.RepairContext == nil
 883: 		cursor := m.theme.CursorMarker(active)
 884: 		check := m.theme.Checkbox(m.scopeFileIncluded(file.Path))
