 889: 	if start > 0 || end < len(m.Scope.Files) {
 890: 		rows = append(rows, fitLine(m.theme.Muted().Render(fmt.Sprintf("…showing %d-%d of %d (j/k to scroll)", start+1, end, len(m.Scope.Files))), innerWidth))
 891: 	}
