 909: func (m Model) activePreviewForSingleColumn() (string, string) {
 910: 	if m.RepairContext != nil {
 911: 		header := m.theme.Section().Render("Repair Review") + "\n" +
 912: 			m.theme.Text().Render("Confirm AI-assisted conflict repair for eligible files before commit execution.") + "\n" +
 913: 			m.theme.Muted().Render("Enter accepts. q cancels.")
 914: 		return "Conflict Files", header + "\n\n" + m.repairPreview()
 915: 	}
 916: 	switch m.Screen {
 917: 	case ScreenScopeReview:
 918: 		return "Diff Preview", m.diffPreview()
 919: 	case ScreenAgentInstruction:
 920: 		caret := m.theme.Accent().Render("│")
 921: 		header := m.theme.Section().Render("Agent Instruction") + "\n"
 922: 		if m.AgentInstruction == "" {
 923: 			header += m.theme.Muted().Render("Optional. Tell the AI how to plan this commit. Enter continues.") + "\n" + caret + " "
 924: 		} else {
 925: 			header += m.theme.Text().Render(m.AgentInstruction) + caret
 926: 		}
