 651: 			" " + c + " ",
 652: 			"(" + c + ")",
 653: 			"[" + c + "]",
 654: 		}
 655: 		lower := strings.ToLower(raw)
 656: 		for _, p := range patterns {
 657: 			if strings.Contains(lower, p) {
 658: 				return true
