 681: func wordWrap(text string, width int) []string {
 682: 	if width <= 0 {
 683: 		return []string{text}
 684: 	}
 685: 	out := []string{}
 686: 	for _, paragraph := range strings.Split(text, "\n") {
 687: 		words := strings.Fields(paragraph)
 688: 		if len(words) == 0 {
 689: 			out = append(out, "")
 690: 			continue
 691: 		}
 692: 		current := words[0]
 693: 		for _, word := range words[1:] {
 694: 			if ansi.StringWidth(current)+1+ansi.StringWidth(word) > width {
 695: 				out = append(out, current)
 696: 				current = word
 697: 				continue
 698: 			}
 699: 			current += " " + word
 700: 		}
 701: 		out = append(out, current)
 702: 	}
 703: 	return out
 704: }
