1069: 		return files, 0, len(files)
1070: 	}
1071: 	start := m.ScopeCursor - maxRows/2
1072: 	if start < 0 {
1073: 		start = 0
1074: 	}
1075: 	end := start + maxRows
1076: 	if end > len(files) {
1077: 		end = len(files)
1078: 		start = end - maxRows
1079: 		if start < 0 {
1080: 			start = 0
1081: 		}
1082: 	}
1083: 	return files[start:end], start, end
