138: 		return ConfigValues{}, nil, err
139: 	}
140: 	if projectConfig == nil {
141: 		return ConfigValues{}, nil, nil
142: 	}
143: 
144: 	sanitized := *projectConfig
145: 	warnings := []string{}
146: 	if sanitized.Provider != nil {
147: 		if sanitized.RecommendedProvider == nil {
148: 			sanitized.RecommendedProvider = sanitized.Provider
149: 		}
150: 		warnings = append(warnings, fmt.Sprintf("Project config at %s contains private `provider`; use `recommendedProvider` for team suggestions.", paths.ProjectConfigPath))
151: 		sanitized.Provider = nil
152: 	}
153: 	if sanitized.Model != nil {
154: 		if sanitized.RecommendedModel == nil {
155: 			sanitized.RecommendedModel = sanitized.Model
156: 		}
157: 		warnings = append(warnings, fmt.Sprintf("Project config at %s contains private `model`; use `recommendedModel` for team suggestions.", paths.ProjectConfigPath))
158: 		sanitized.Model = nil
159: 	}
160: 	if sanitized.BaseURL != nil {
161: 		warnings = append(warnings, fmt.Sprintf("Project config at %s contains private `baseURL`; project-level provider endpoints are ignored.", paths.ProjectConfigPath))
162: 		sanitized.BaseURL = nil
163: 	}
164: 	if sanitized.APIKey != nil {
165: 		warnings = append(warnings, fmt.Sprintf("Project config at %s contains `apiKey`; project-level secrets are ignored.", paths.ProjectConfigPath))
166: 		sanitized.APIKey = nil
167: 	}
168: 
169: 	return sanitized, warnings, nil
170: }
