218: func ResolveEffectiveConfig(options ResolveConfigOptions) (ResolvedConfig, error) {
219: 	paths := GetConfigPaths(ConfigEnvironment{CWD: options.CWD, Env: options.Env})
220: 	userConfig, err := LoadUserConfig(ConfigEnvironment{CWD: options.CWD, Env: options.Env})
221: 	if err != nil {
222: 		return ResolvedConfig{}, err
223: 	}
224: 	projectConfig, warnings, err := LoadProjectConfig(ConfigEnvironment{CWD: options.CWD, Env: options.Env})
225: 	if err != nil {
226: 		return ResolvedConfig{}, err
227: 	}
228: 	envConfig, err := GetEnvConfig(options.Env)
229: 	if err != nil {
230: 		return ResolvedConfig{}, err
231: 	}
232: 	flagOverrides := normalizeConfig(options.FlagOverrides)
233: 	merged := mergeConfigs(userConfig, projectConfig, envConfig, flagOverrides)
234: 	provider := effectiveProvider(merged)
235: 	promptStyle := effectivePromptStyle(merged)
236: 	messageLanguage := effectiveMessageLanguage(merged)
237: 	model := GetDefaultModel(provider)
238: 	if merged.Model != nil {
239: 		model = *merged.Model
240: 	}
241: 	apiKey, apiKeySource, err := resolveAPIKey(provider, userConfig, envConfig, flagOverrides, options.SecretStore)
242: 	if err != nil {
243: 		return ResolvedConfig{}, err
244: 	}
245: 	standingInstruction := combineStandingInstructions(projectConfig.StandingInstruction, userConfig.StandingInstruction, envConfig.StandingInstruction, flagOverrides.StandingInstruction)
246: 
247: 	return ResolvedConfig{
248: 		Paths:         paths,
249: 		UserConfig:    userConfig,
250: 		ProjectConfig: projectConfig,
251: 		EnvConfig:     envConfig,
252: 		FlagOverrides: flagOverrides,
253: 		Warnings:      warnings,
254: 		Values: EffectiveConfig{
255: 			APIKey:              apiKey,
256: 			APIKeySource:        apiKeySource,
257: 			BaseURL:             merged.BaseURL,
258: 			MessageLanguage:     messageLanguage,
259: 			Model:               model,
260: 			PromptStyle:         promptStyle,
261: 			Provider:            provider,
262: 			RecommendedModel:    merged.RecommendedModel,
263: 			RecommendedProvider: merged.RecommendedProvider,
264: 			StandingInstruction: standingInstruction,
265: 		},
266: 	}, nil
267: }
