497: func readOptionalConfigFile(path string, sourceLabel string) (*ConfigValues, error) {
498: 	content, err := os.ReadFile(path)
499: 	if err != nil {
500: 		if errors.Is(err, os.ErrNotExist) {
501: 			return nil, nil
502: 		}
503: 		return nil, newError("Unable to read %s at %s.", sourceLabel, path)
504: 	}
505: 
506: 	var payload map[string]any
507: 	if err := json.Unmarshal(content, &payload); err != nil {
508: 		return nil, newError("%s at %s is not valid JSON.", sourceLabel, path)
509: 	}
510: 
511: 	parsed, err := parseConfigObject(payload, fmt.Sprintf("%s at %s", sourceLabel, path))
512: 	if err != nil {
513: 		return nil, err
514: 	}
515: 	return &parsed, nil
516: }
