617: func ensureNonEmptyString(value any, key ConfigKey, sourceLabel string) (string, error) {
618: 	stringValue, ok := value.(string)
619: 	if !ok {
620: 		return "", newError("%s has an invalid `%s` value; expected a string.", sourceLabel, key)
