738: func sourceForSingleValue(flag any, env any, project any, user any) ConfigValueSource {
739: 	if !isNilValue(flag) {
740: 		return ConfigValueSourceFlag
741: 	}
742: 	if !isNilValue(env) {
743: 		return ConfigValueSourceEnv
744: 	}
745: 	if !isNilValue(project) {
746: 		return ConfigValueSourceProject
747: 	}
748: 	if !isNilValue(user) {
749: 		return ConfigValueSourceUser
750: 	}
751: 	return ConfigValueSourceDefault
752: }
