754: func sourceForAPIKey(source APIKeySource) ConfigValueSource {
755: 	switch source {
756: 	case APIKeySourceEnv:
757: 		return ConfigValueSourceEnv
758: 	case APIKeySourceSecretStore:
759: 		return ConfigValueSourceSecretStore
760: 	case APIKeySourcePlaintextConfig:
761: 		return ConfigValueSourceUser
762: 	default:
763: 		return ConfigValueSourceMissing
764: 	}
765: }
