767: func sourceListForStandingInstruction(project *string, user *string, env *string, flag *string) string {
768: 	sources := make([]string, 0, 4)
769: 	if project != nil {
770: 		sources = append(sources, string(ConfigValueSourceProject))
771: 	}
772: 	if user != nil {
773: 		sources = append(sources, string(ConfigValueSourceUser))
774: 	}
775: 	if env != nil {
776: 		sources = append(sources, string(ConfigValueSourceEnv))
777: 	}
778: 	if flag != nil {
779: 		sources = append(sources, string(ConfigValueSourceFlag))
780: 	}
781: 	if len(sources) == 0 {
782: 		return string(ConfigValueSourceDefault)
783: 	}
784: 	return strings.Join(sources, ",")
785: }
