787: func isNilValue(value any) bool {
788: 	if value == nil {
789: 		return true
790: 	}
791: 	switch typed := value.(type) {
792: 	case *ProviderType:
793: 		return typed == nil
794: 	case *PromptStyle:
795: 		return typed == nil
796: 	case *MessageLanguage:
797: 		return typed == nil
798: 	case *string:
799: 		return typed == nil
800: 	default:
801: 		return false
802: 	}
803: }
