269: func ParseKeyValue(key string, rawValue string) (ConfigValues, error) {
270: 	if !IsConfigKey(key) {
271: 		return ConfigValues{}, newError("Unsupported config key `%s`.", key)
272: 	}
273: 
274: 	value, err := ensureNonEmptyString(rawValue, ConfigKey(key), "CLI input")
275: 	if err != nil {
276: 		return ConfigValues{}, err
277: 	}
278: 
279: 	switch ConfigKey(key) {
280: 	case ConfigKeyProvider:
281: 		if !IsProviderType(value) {
282: 			return ConfigValues{}, newError("Unsupported provider `%s`.", value)
283: 		}
284: 		provider := ProviderType(value)
285: 		return ConfigValues{Provider: &provider}, nil
286: 	case ConfigKeyPromptStyle:
287: 		if !IsPromptStyle(value) {
288: 			return ConfigValues{}, newError("Unsupported prompt style `%s`.", value)
289: 		}
290: 		promptStyle := PromptStyle(value)
291: 		return ConfigValues{PromptStyle: &promptStyle}, nil
292: 	case ConfigKeyMessageLanguage:
293: 		if !IsMessageLanguage(value) {
294: 			return ConfigValues{}, newError("Unsupported message language `%s`.", value)
295: 		}
296: 		messageLanguage := MessageLanguage(value)
297: 		return ConfigValues{MessageLanguage: &messageLanguage}, nil
298: 	case ConfigKeyStandingInstruction:
299: 		return ConfigValues{StandingInstruction: &value}, nil
300: 	case ConfigKeyRecommendedProvider:
301: 		if !IsProviderType(value) {
302: 			return ConfigValues{}, newError("Unsupported provider recommendation `%s`.", value)
303: 		}
304: 		provider := ProviderType(value)
305: 		return ConfigValues{RecommendedProvider: &provider}, nil
306: 	case ConfigKeyRecommendedModel:
307: 		return ConfigValues{RecommendedModel: &value}, nil
308: 	case ConfigKeyAPIKey:
309: 		return ConfigValues{APIKey: &value}, nil
310: 	case ConfigKeyBaseURL:
311: 		return ConfigValues{BaseURL: &value}, nil
312: 	case ConfigKeyModel:
313: 		return ConfigValues{Model: &value}, nil
314: 	default:
315: 		return ConfigValues{}, newError("Unsupported config key `%s`.", key)
316: 	}
317: }
