319: func WriteUserConfig(config ConfigValues, options ConfigEnvironment) (WriteUserConfigResult, error) {
320: 	paths := GetConfigPaths(options)
321: 	if err := os.MkdirAll(paths.UserConfigHome, 0o755); err != nil {
322: 		return WriteUserConfigResult{}, newError("Unable to create user config directory at %s.", paths.UserConfigHome)
323: 	}
324: 
325: 	content, err := json.MarshalIndent(config, "", "  ")
326: 	if err != nil {
327: 		return WriteUserConfigResult{}, err
328: 	}
329: 	content = append(content, '\n')
330: 
331: 	if err := os.WriteFile(paths.UserConfigPath, content, 0o600); err != nil {
332: 		return WriteUserConfigResult{}, newError("Unable to write user config at %s.", paths.UserConfigPath)
333: 	}
334: 
335: 	warnings := []string{}
336: 	if runtime.GOOS != "windows" {
337: 		if err := os.Chmod(paths.UserConfigPath, 0o600); err != nil {
338: 			warnings = append(warnings, fmt.Sprintf("Unable to set 0600 permissions on user config at %s.", paths.UserConfigPath))
339: 		}
340: 	}
341: 
342: 	return WriteUserConfigResult{Path: paths.UserConfigPath, Stored: config, Warnings: warnings}, nil
343: }
