435: func SummarizeConfigSources(resolved ResolvedConfig) ConfigSourceSummary {
436: 	return ConfigSourceSummary{
437: 		Provider:            sourceForSingleValue(resolved.FlagOverrides.Provider, resolved.EnvConfig.Provider, resolved.ProjectConfig.Provider, resolved.UserConfig.Provider),
438: 		Model:               sourceForSingleValue(resolved.FlagOverrides.Model, resolved.EnvConfig.Model, resolved.ProjectConfig.Model, resolved.UserConfig.Model),
