440: 		PromptStyle:         sourceForSingleValue(resolved.FlagOverrides.PromptStyle, resolved.EnvConfig.PromptStyle, resolved.ProjectConfig.PromptStyle, resolved.UserConfig.PromptStyle),
441: 		MessageLanguage:     sourceForSingleValue(resolved.FlagOverrides.MessageLanguage, resolved.EnvConfig.MessageLanguage, resolved.ProjectConfig.MessageLanguage, resolved.UserConfig.MessageLanguage),
442: 		StandingInstruction: sourceListForStandingInstruction(resolved.ProjectConfig.StandingInstruction, resolved.UserConfig.StandingInstruction, resolved.EnvConfig.StandingInstruction, resolved.FlagOverrides.StandingInstruction),
443: 	}
