596: 	}
597: 
598: 	if rawRecommendedModel, ok := raw[string(ConfigKeyRecommendedModel)]; ok {
599: 		recommendedModel, err := ensureNonEmptyString(rawRecommendedModel, ConfigKeyRecommendedModel, sourceLabel)
600: 		if err != nil {
601: 			return ConfigValues{}, err
602: 		}
603: 		parsed.RecommendedModel = &recommendedModel
604: 	}
605: 
606: 	if rawAPIKey, ok := raw[string(ConfigKeyAPIKey)]; ok {
607: 		apiKey, err := ensureNonEmptyString(rawAPIKey, ConfigKeyAPIKey, sourceLabel)
608: 		if err != nil {
609: 			return ConfigValues{}, err
610: 		}
611: 		parsed.APIKey = &apiKey
612: 	}
613: 
614: 	return parsed, nil
