719: 	}
720: 	if envConfig.APIKey != nil {
721: 		return envConfig.APIKey, APIKeySourceEnv, nil
722: 	}
723: 	if store != nil {
724: 		apiKey, err := store.GetAPIKey(provider)
725: 		if err != nil {
726: 			return nil, APIKeySourceMissing, newError("Unable to read API key from Secret Store for %s.", provider)
727: 		}
728: 		if apiKey != nil && strings.TrimSpace(*apiKey) != "" {
729: 			return apiKey, APIKeySourceSecretStore, nil
730: 		}
731: 	}
732: 	if userConfig.APIKey != nil {
733: 		return userConfig.APIKey, APIKeySourcePlaintextConfig, nil
734: 	}
735: 	return nil, APIKeySourceMissing, nil
736: }
