353: func SaveAPIKeyToSecretStore(provider ProviderType, apiKey string, store WritableSecretStore) (SaveAPIKeyResult, error) {
354: 	if store == nil {
355: 		warning := "Secret Store is not available; use --plaintext-api-key to store this key in user config."
356: 		return SaveAPIKeyResult{Provider: provider, Source: APIKeySourceMissing, Stored: false, Warning: &warning}, nil
357: 	}
358: 	if err := store.SetAPIKey(provider, apiKey); err != nil {
359: 		return SaveAPIKeyResult{}, newError("Unable to write API key to Secret Store for %s.", provider)
360: 	}
361: 	return SaveAPIKeyResult{Provider: provider, Source: APIKeySourceSecretStore, Stored: true}, nil
362: }
