518: func parseConfigObject(raw map[string]any, sourceLabel string) (ConfigValues, error) {
519: 	parsed := ConfigValues{}
520: 	for key := range raw {
521: 		if !IsConfigKey(key) {
522: 			return ConfigValues{}, newError("Unsupported config key `%s` in %s.", key, sourceLabel)
523: 		}
524: 	}
525: 
526: 	if rawProvider, ok := raw[string(ConfigKeyProvider)]; ok {
527: 		provider, err := ensureNonEmptyString(rawProvider, ConfigKeyProvider, sourceLabel)
528: 		if err != nil {
529: 			return ConfigValues{}, err
530: 		}
531: 		if !IsProviderType(provider) {
532: 			return ConfigValues{}, newError("%s has unsupported `provider` value `%s`.", sourceLabel, provider)
533: 		}
534: 		providerType := ProviderType(provider)
535: 		parsed.Provider = &providerType
536: 	}
537: 
538: 	if rawModel, ok := raw[string(ConfigKeyModel)]; ok {
539: 		model, err := ensureNonEmptyString(rawModel, ConfigKeyModel, sourceLabel)
540: 		if err != nil {
541: 			return ConfigValues{}, err
542: 		}
543: 		parsed.Model = &model
544: 	}
545: 
546: 	if rawBaseURL, ok := raw[string(ConfigKeyBaseURL)]; ok {
547: 		baseURL, err := ensureNonEmptyString(rawBaseURL, ConfigKeyBaseURL, sourceLabel)
548: 		if err != nil {
549: 			return ConfigValues{}, err
550: 		}
551: 		parsed.BaseURL = &baseURL
552: 	}
553: 
554: 	if rawPromptStyle, ok := raw[string(ConfigKeyPromptStyle)]; ok {
555: 		promptStyle, err := ensureNonEmptyString(rawPromptStyle, ConfigKeyPromptStyle, sourceLabel)
556: 		if err != nil {
557: 			return ConfigValues{}, err
558: 		}
559: 		if !IsPromptStyle(promptStyle) {
560: 			return ConfigValues{}, newError("%s has unsupported `promptStyle` value `%s`.", sourceLabel, promptStyle)
561: 		}
562: 		style := PromptStyle(promptStyle)
563: 		parsed.PromptStyle = &style
564: 	}
565: 
566: 	if rawMessageLanguage, ok := raw[string(ConfigKeyMessageLanguage)]; ok {
567: 		messageLanguage, err := ensureNonEmptyString(rawMessageLanguage, ConfigKeyMessageLanguage, sourceLabel)
568: 		if err != nil {
569: 			return ConfigValues{}, err
570: 		}
571: 		if !IsMessageLanguage(messageLanguage) {
572: 			return ConfigValues{}, newError("%s has unsupported `messageLanguage` value `%s`.", sourceLabel, messageLanguage)
573: 		}
574: 		language := MessageLanguage(messageLanguage)
575: 		parsed.MessageLanguage = &language
576: 	}
577: 
578: 	if rawStandingInstruction, ok := raw[string(ConfigKeyStandingInstruction)]; ok {
579: 		standingInstruction, err := ensureNonEmptyString(rawStandingInstruction, ConfigKeyStandingInstruction, sourceLabel)
580: 		if err != nil {
581: 			return ConfigValues{}, err
582: 		}
583: 		parsed.StandingInstruction = &standingInstruction
584: 	}
585: 
586: 	if rawRecommendedProvider, ok := raw[string(ConfigKeyRecommendedProvider)]; ok {
587: 		recommendedProvider, err := ensureNonEmptyString(rawRecommendedProvider, ConfigKeyRecommendedProvider, sourceLabel)
588: 		if err != nil {
589: 			return ConfigValues{}, err
590: 		}
591: 		if !IsProviderType(recommendedProvider) {
592: 			return ConfigValues{}, newError("%s has unsupported `recommendedProvider` value `%s`.", sourceLabel, recommendedProvider)
593: 		}
594: 		provider := ProviderType(recommendedProvider)
595: 		parsed.RecommendedProvider = &provider
596: 	}
597: 
598: 	if rawRecommendedModel, ok := raw[string(ConfigKeyRecommendedModel)]; ok {
599: 		recommendedModel, err := ensureNonEmptyString(rawRecommendedModel, ConfigKeyRecommendedModel, sourceLabel)
600: 		if err != nil {
601: 			return ConfigValues{}, err
602: 		}
603: 		parsed.RecommendedModel = &recommendedModel
604: 	}
605: 
606: 	if rawAPIKey, ok := raw[string(ConfigKeyAPIKey)]; ok {
607: 		apiKey, err := ensureNonEmptyString(rawAPIKey, ConfigKeyAPIKey, sourceLabel)
608: 		if err != nil {
609: 			return ConfigValues{}, err
610: 		}
611: 		parsed.APIKey = &apiKey
612: 	}
613: 
614: 	return parsed, nil
615: }
