805: func combineStandingInstructions(values ...*string) *string {
806: 	parts := make([]string, 0, len(values))
807: 	for _, value := range values {
808: 		if value == nil {
809: 			continue
810: 		}
811: 		trimmed := strings.TrimSpace(*value)
812: 		if trimmed != "" {
813: 			parts = append(parts, trimmed)
814: 		}
815: 	}
816: 	if len(parts) == 0 {
817: 		return nil
818: 	}
819: 	return stringPtr(strings.Join(parts, "\n\n"))
820: }
