254: func runOnboardingTUI(runtime InitRuntime, current config.EffectiveConfig) int {
255: 	prefill := OnboardingPrefill{
256: 		Provider:        current.Provider,
257: 		Model:           current.Model,
258: 		PromptStyle:     current.PromptStyle,
259: 		MessageLanguage: current.MessageLanguage,
260: 	}
261: 	if current.BaseURL != nil {
262: 		prefill.BaseURL = *current.BaseURL
263: 	}
264: 	if current.StandingInstruction != nil {
265: 		prefill.StandingInstruction = *current.StandingInstruction
266: 	}
267: 	answers, err := runtime.OnboardingRunner(prefill)
268: 	if err != nil {
269: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
270: 		return int(output.Error)
271: 	}
272: 	if answers.Cancelled {
273: 		fmt.Fprintln(runtime.Stderr, "Onboarding cancelled. No configuration changes were saved.")
274: 		return int(output.UserCancel)
275: 	}
276: 	provider := answers.Provider
277: 	if provider == "" {
278: 		provider = config.DefaultProvider
279: 	}
280: 	model := strings.TrimSpace(answers.Model)
281: 	if model == "" {
282: 		model = config.GetDefaultModel(provider)
283: 	}
284: 	style := answers.PromptStyle
285: 	if style == "" {
286: 		style = config.DefaultPromptStyle
287: 	}
288: 	language := answers.MessageLanguage
289: 	if language == "" {
290: 		language = config.DefaultMessageLanguage
291: 	}
292: 	apiKey := strings.TrimSpace(answers.APIKey)
293: 	if apiKey == "" {
294: 		fmt.Fprintln(runtime.Stderr, "error: API key is required")
295: 		return int(output.Error)
296: 	}
297: 	save, err := config.SaveAPIKeyToSecretStore(provider, apiKey, runtime.SecretStore)
298: 	if err != nil {
299: 		fmt.Fprintf(runtime.Stderr, "error: %v Use --plaintext-api-key to store this key in user config instead.\n", err)
300: 		return int(output.Error)
301: 	}
302: 	if !save.Stored {
303: 		message := "Secret Store is not available; use --plaintext-api-key to store this key in user config."
304: 		if save.Warning != nil {
305: 			message = *save.Warning
306: 		}
307: 		fmt.Fprintf(runtime.Stderr, "error: %s\n", message)
308: 		return int(output.Error)
309: 	}
310: 	var baseURL *string
311: 	if provider == config.ProviderOpenAICompatible || strings.TrimSpace(answers.BaseURL) != "" {
312: 		baseURL = optionalStringPointer(answers.BaseURL)
313: 	}
314: 	patch := config.ConfigValues{
315: 		Provider:            &provider,
316: 		Model:               &model,
317: 		BaseURL:             baseURL,
318: 		PromptStyle:         &style,
319: 		MessageLanguage:     &language,
320: 		StandingInstruction: optionalStringPointer(answers.StandingInstruction),
321: 	}
322: 	result, err := config.WriteUserConfigPatch(patch, config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
323: 	if err != nil {
324: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
325: 		return int(output.Error)
326: 	}
327: 	for _, warning := range result.Warnings {
328: 		fmt.Fprintln(runtime.Stderr, "Warning: "+warning)
329: 	}
330: 	fmt.Fprintf(runtime.Stdout, "Initialized user config at %s.\n", result.Path)
331: 	fmt.Fprintf(runtime.Stdout, "Stored API key in Secret Store for %s.\n", save.Provider)
332: 	effective := config.EffectiveConfig{
333: 		Provider:            provider,
334: 		Model:               model,
335: 		BaseURL:             baseURL,
336: 		PromptStyle:         style,
337: 		MessageLanguage:     language,
338: 		APIKey:              &apiKey,
339: 		APIKeySource:        config.APIKeySourceSecretStore,
340: 		StandingInstruction: optionalStringPointer(answers.StandingInstruction),
341: 	}
342: 	for _, line := range config.ToHumanConfigLines(effective) {
343: 		fmt.Fprintln(runtime.Stdout, line)
344: 	}
345: 	return int(output.Success)
346: }
