201: func parseGeminiTurn(payload []byte) (runtimex.ProviderTurn, error) {
202: 	var response struct {
203: 		Candidates []struct {
204: 			Content struct {
205: 				Parts []struct {
206: 					FunctionCall *struct {
207: 						Name string         `json:"name"`
208: 						Args map[string]any `json:"args"`
209: 					} `json:"functionCall"`
210: 				} `json:"parts"`
211: 			} `json:"content"`
212: 		} `json:"candidates"`
213: 	}
214: 	if err := json.Unmarshal(payload, &response); err != nil {
215: 		return runtimex.ProviderTurn{}, err
216: 	}
217: 	calls := make([]runtimex.ToolCallRequest, 0)
218: 	for _, candidate := range response.Candidates {
219: 		for _, part := range candidate.Content.Parts {
220: 			if part.FunctionCall == nil {
221: 				continue
222: 			}
223: 			name := part.FunctionCall.Name
224: 			calls = append(calls, runtimex.ToolCallRequest{ID: name, Name: runtimex.ToolName(name), Arguments: cloneArguments(part.FunctionCall.Args)})
225: 		}
226: 	}
227: 	return runtimex.ProviderTurn{ToolCalls: calls}, nil
228: }
229: 
230: func buildGeminiToolResultPayload(results []runtimex.ToolCallResult) ([]byte, error) {
231: 	parts := make([]map[string]any, 0, len(results))
232: 	for _, result := range results {
233: 		object, err := toolResultMap(result)
234: 		if err != nil {
235: 			return nil, err
236: 		}
237: 		parts = append(parts, map[string]any{"functionResponse": map[string]any{"name": string(result.Name), "response": object}})
238: 	}
239: 	return json.Marshal(map[string]any{"contents": []map[string]any{{"role": "function", "parts": parts}}})
240: }
241: 
242: func buildGeminiInitialRequest(tools []runtimex.ToolName) ([]byte, error) {
243: 	declarations := make([]map[string]any, 0, len(tools))
244: 	for _, tool := range tools {
245: 		declarations = append(declarations, map[string]any{
246: 			"name":        string(tool),
247: 			"description": toolDescription(tool),
248: 			"parameters":  toolSchema(tool),
249: 		})
250: 	}
251: 	return json.Marshal(map[string]any{"tools": []map[string]any{{"functionDeclarations": declarations}}})
252: }
253: 
254: func openAIFunctionTools(tools []runtimex.ToolName) []map[string]any {
255: 	items := make([]map[string]any, 0, len(tools))
256: 	for _, tool := range tools {
257: 		items = append(items, map[string]any{
258: 			"type": "function",
259: 			"function": map[string]any{
260: 				"name":        string(tool),
261: 				"description": toolDescription(tool),
262: 				"parameters":  toolSchema(tool),
263: 			},
264: 		})
265: 	}
266: 	return items
267: }
268: 
269: func openAIResponsesFunctionTools(tools []runtimex.ToolName) []map[string]any {
270: 	items := make([]map[string]any, 0, len(tools))
271: 	for _, tool := range tools {
272: 		items = append(items, map[string]any{
273: 			"type":        "function",
274: 			"name":        string(tool),
275: 			"description": toolDescription(tool),
276: 			"parameters":  toolSchema(tool),
277: 		})
278: 	}
279: 	return items
280: }
281: 
282: func parseToolArgumentsString(raw string) (map[string]any, error) {
283: 	if strings.TrimSpace(raw) == "" {
284: 		return map[string]any{}, nil
285: 	}
286: 	var arguments map[string]any
287: 	if err := json.Unmarshal([]byte(raw), &arguments); err != nil {
288: 		return nil, fmt.Errorf("provider returned malformed tool arguments: %w", err)
289: 	}
290: 	return arguments, nil
291: }
292: 
293: func encodeToolResult(result runtimex.ToolCallResult) (string, error) {
294: 	object, err := toolResultMap(result)
295: 	if err != nil {
296: 		return "", err
297: 	}
298: 	buffer, err := json.Marshal(object)
299: 	if err != nil {
300: 		return "", err
301: 	}
302: 	return string(buffer), nil
303: }
304: 
305: func toolResultObject(result runtimex.ToolCallResult) (string, error) {
306: 	return encodeToolResult(result)
307: }
308: 
309: func toolResultMap(result runtimex.ToolCallResult) (map[string]any, error) {
310: 	object := map[string]any{"ok": result.OK}
311: 	if result.OK {
312: 		object["result"] = result.Result
313: 	} else if result.Error != nil {
314: 		object["error"] = result.Error
315: 	} else {
316: 		object["error"] = map[string]any{"code": "tool_failed", "message": "tool call failed"}
317: 	}
318: 	return object, nil
319: }
320: 
321: func cloneArguments(arguments map[string]any) map[string]any {
322: 	cloned := make(map[string]any, len(arguments))
323: 	for key, value := range arguments {
324: 		cloned[key] = value
325: 	}
326: 	return cloned
327: }

