143: 		if strings.TrimSpace(value) != "" {
144: 			return strings.TrimSpace(value)
145: 		}
146: 	}
147: 	return ""
148: }
149: 
150: func detectGitVersion(cwd string, env map[string]string) (*string, bool) {
151: 	result, err := gitpkg.DefaultCommandRunner(cwd, []string{"--version"}, env)
152: 	if err != nil || result.ExitCode != 0 {
153: 		return nil, false
154: 	}
155: 	version := strings.TrimSpace(result.Stdout)
156: 	if version == "" {
157: 		return nil, false
158: 	}
159: 	return &version, true
160: }
161: 
162: func collectConfigIssues(resolved config.ResolvedConfig, inspection gitpkg.Inspection) []Issue {
163: 	issues := make([]Issue, 0)
164: 	defaultProviderOnly := resolved.UserConfig.Provider == nil && resolved.ProjectConfig.Provider == nil && resolved.EnvConfig.Provider == nil
165: 	defaultModelOnly := resolved.UserConfig.Model == nil && resolved.ProjectConfig.Model == nil && resolved.EnvConfig.Model == nil
166: 	if defaultProviderOnly && defaultModelOnly {
167: 		issues = append(issues, Issue{Code: "provider_config_missing", Check: "effectiveConfig", Message: "Provider configuration is still using built-in defaults; run `cnm init` or configure cnm before generating commits.", Severity: SeverityError})
168: 	}
169: 	if resolved.Values.APIKey == nil || strings.TrimSpace(*resolved.Values.APIKey) == "" {
170: 		issues = append(issues, Issue{Code: "api_key_missing", Check: "effectiveConfig", Message: "No API key is configured for " + string(resolved.Values.Provider) + ".", Severity: SeverityError})
171: 	}
172: 	if resolved.Values.Provider == config.ProviderOpenAICompatible && (resolved.Values.BaseURL == nil || strings.TrimSpace(*resolved.Values.BaseURL) == "") {
173: 		issues = append(issues, Issue{Code: "provider_config_missing", Check: "effectiveConfig", Message: "The openai-compatible provider requires `baseURL` to be configured.", Severity: SeverityError})
174: 	}
175: 	if !inspection.Repository.HasGitIdentity && inspection.Repository.IsRepository {
176: 		issues = append(issues, Issue{Code: "git_identity_missing", Check: "repository", Message: "Git user.name and user.email must be configured before committing.", Severity: SeverityError})
177: 	}
178: 	return issues
179: }
180: 
181: func sourceLabel(user bool, project bool, env bool, hasDefault bool) string {
182: 	if env {
183: 		return "env"
184: 	}
185: 	if project {
186: 		return "project"
187: 	}
188: 	if user {
189: 		return "user"
190: 	}
191: 	if hasDefault {
192: 		return "default"
193: 	}
194: 	return "missing"
195: }
196: 
197: func hasInsecureUserConfigPermissions(path string) bool {
198: 	if runtime.GOOS == "windows" || strings.TrimSpace(path) == "" {
199: 		return false
200: 	}
201: 	info, err := os.Stat(path)
202: 	if err != nil {
203: 		return false
204: 	}
205: 	return info.Mode().Perm()&0o077 != 0
206: }

