  1: package security
  2: 
  3: import (
  4: 	"regexp"
  5: 	"strings"
  6: )
  7: 
  8: type SecretSeverity string
  9: 
 10: const (
 11: 	SecretSeverityWarning  SecretSeverity = "warning"
 12: 	SecretSeverityBlocking SecretSeverity = "blocking"
 13: )
 14: 
 15: type SecretFinding struct {
 16: 	Code        string         `json:"code"`
 17: 	Description string         `json:"description"`
 18: 	Line        int            `json:"line"`
 19: 	Excerpt     string         `json:"excerpt"`
 20: 	Severity    SecretSeverity `json:"severity"`
 21: }
 22: 
 23: type SecretScanResult struct {
 24: 	Findings            []SecretFinding `json:"findings"`
 25: 	HasBlockingFindings bool            `json:"hasBlockingFindings"`
 26: }
 27: 
 28: type secretPattern struct {
 29: 	code        string
 30: 	description string
 31: 	expression  *regexp.Regexp
 32: 	severity    SecretSeverity
 33: }
 34: 
 35: var secretPatterns = []secretPattern{
 36: 	{
 37: 		code:        "private_key",
 38: 		description: "Private key material appears in the diff.",
 39: 		expression:  regexp.MustCompile(`(?i)-----BEGIN (?:RSA |DSA |EC |OPENSSH |PGP )?PRIVATE KEY-----`),
 40: 		severity:    SecretSeverityWarning,
 41: 	},
 42: 	{
 43: 		code:        "aws_access_key",
 44: 		description: "AWS access key-like token appears in the diff.",
 45: 		expression:  regexp.MustCompile(`\b(?:AKIA|ASIA)[A-Z0-9]{16}\b`),
 46: 		severity:    SecretSeverityWarning,
 47: 	},
 48: 	{
 49: 		code:        "provider_api_key",
 50: 		description: "Provider API key-like token appears in the diff.",
 51: 		expression:  regexp.MustCompile(`(?i)\b(?:sk|xox[baprs]|ghp|github_pat)_[A-Za-z0-9_\-]{16,}\b`),
 52: 		severity:    SecretSeverityWarning,
 53: 	},
 54: 	{
 55: 		code:        "assigned_secret",
 56: 		description: "Secret-looking assignment appears in the diff.",
 57: 		expression:  regexp.MustCompile(`(?i)(?:api[_-]?key|secret|token|password)\s*[:=]\s*["'][^"'\s]{12,}["']`),
 58: 		severity:    SecretSeverityWarning,
 59: 	},
 60: }
 61: 
 62: var excerptRedactor = regexp.MustCompile(`(["'=:\s])([A-Za-z0-9_\-/+]{8})[A-Za-z0-9_\-/+]{4,}(["'\s]|$)`)
 63: 
 64: func ScanTextForSecrets(text string) SecretScanResult {
 65: 	findings := make([]SecretFinding, 0)
 66: 	lines := strings.Split(strings.ReplaceAll(text, "\r\n", "\n"), "\n")
 67: 
 68: 	for index, line := range lines {
 69: 		for _, pattern := range secretPatterns {
 70: 			if pattern.expression.MatchString(line) {
 71: 				findings = append(findings, SecretFinding{
 72: 					Code:        pattern.code,
 73: 					Description: pattern.description,
 74: 					Line:        index + 1,
 75: 					Excerpt:     redactExcerpt(line),
 76: 					Severity:    pattern.severity,
 77: 				})
 78: 			}
 79: 		}
 80: 	}
 81: 
 82: 	result := SecretScanResult{Findings: findings}
 83: 	for _, finding := range findings {
 84: 		if finding.Severity == SecretSeverityBlocking {
 85: 			result.HasBlockingFindings = true
 86: 			break
 87: 		}
 88: 	}
 89: 
 90: 	return result
 91: }
 92: 
 93: func redactExcerpt(line string) string {
 94: 	redacted := excerptRedactor.ReplaceAllString(line, `$1$2…$3`)
 95: 	runes := []rune(redacted)
 96: 	if len(runes) > 160 {
 97: 		return string(runes[:160])
 98: 	}
 99: 	return redacted
100: }

