  1: #!/usr/bin/env node
  2: 
  3: const fs = require("node:fs");
  4: const path = require("node:path");
  5: const os = require("node:os");
  6: const https = require("node:https");
  7: const { spawnSync } = require("node:child_process");
  8: 
  9: const pkg = require("../package.json");
 10: const {
 11: 	archiveNameFor,
 12: 	archName,
 13: 	createInstallerSessionPaths,
 14: 	findBinary,
 15: 	parseChecksums,
 16: 	platformName,
 17: 	targetExecutableName,
 18: 	verifyFileChecksum,
 19: } = require("./npm-install-lib");
 20: const version = pkg.version;
 21: const owner = process.env.CNM_RELEASE_OWNER || "ByteTrue";
 22: const repo = process.env.CNM_RELEASE_REPO || "commit-now-myfriend";
 23: const baseUrl =
 24: 	process.env.CNM_RELEASE_BASE_URL ||
 25: 	`https://github.com/${owner}/${repo}/releases/download/v${version}`;
 26: const binDir =
 27: 	process.env.CNM_INSTALL_BIN_DIR || path.join(__dirname, "..", "bin");
 28: const targetName = targetExecutableName(process.platform);
 29: const targetPath = path.join(binDir, targetName);
 30: 
 31: function download(url, destination) {
 32: 	return new Promise((resolve, reject) => {
 33: 		const file = fs.createWriteStream(destination);
 34: 		const request = https.get(url, (response) => {
 35: 			if (
 36: 				response.statusCode >= 300 &&
 37: 				response.statusCode < 400 &&
 38: 				response.headers.location
 39: 			) {
 40: 				file.close(() => fs.rmSync(destination, { force: true }));
 41: 				return resolve(download(response.headers.location, destination));
 42: 			}
 43: 			if (response.statusCode !== 200) {
 44: 				file.close(() => fs.rmSync(destination, { force: true }));
 45: 				return reject(
 46: 					new Error(
 47: 						`Download failed with HTTP ${response.statusCode} for ${url}`,
 48: 					),
 49: 				);
 50: 			}
 51: 			response.pipe(file);
 52: 			file.on("finish", () => file.close(resolve));
 53: 		});
 54: 		request.on("error", (error) => {
 55: 			file.close(() => fs.rmSync(destination, { force: true }));
 56: 			reject(error);
 57: 		});
 58: 	});
 59: }
 60: 
 61: function extract(archivePath, destination, osName) {
 62: 	if (osName === "windows") {
 63: 		const powershell = spawnSync(
 64: 			"powershell.exe",
 65: 			[
 66: 				"-NoProfile",
 67: 				"-Command",
 68: 				`Expand-Archive -LiteralPath '${archivePath}' -DestinationPath '${destination}' -Force`,
 69: 			],
 70: 			{ stdio: "inherit" },
 71: 		);
 72: 		if (powershell.status !== 0) {
 73: 			throw new Error(
 74: 				"Failed to extract Windows archive with PowerShell Expand-Archive.",
 75: 			);
 76: 		}
 77: 		return;
 78: 	}
 79: 	const tar = spawnSync("tar", ["-xzf", archivePath, "-C", destination], {
 80: 		stdio: "inherit",
 81: 	});
 82: 	if (tar.status !== 0) {
 83: 		throw new Error("Failed to extract release archive with tar.");
 84: 	}
 85: }
 86: 
 87: async function main() {
 88: 	const osName = platformName(process.platform);
 89: 	const arch = archName(process.arch);
 90: 	if (!osName || !arch) {
 91: 		console.warn(
 92: 			`[cnm] No prebuilt binary is published for ${process.platform}/${process.arch}.`,
 93: 		);
 94: 		console.warn(
 95: 			"[cnm] Install a release binary manually or build from source with `make go-build`.",
 96: 		);
 97: 		return;
 98: 	}
 99: 
100: 	fs.mkdirSync(binDir, { recursive: true });
101: 	const archiveName = archiveNameFor(version, osName, arch);
102: 	const tmpRoot = process.env.CNM_INSTALL_TMP_DIR || os.tmpdir();
103: 	const { archivePath, checksumsPath, extractDir } =
104: 		createInstallerSessionPaths(tmpRoot, archiveName, version);
105: 	const url = `${baseUrl}/${archiveName}`;
106: 	const checksumsUrl = `${baseUrl}/checksums.txt`;
107: 
108: 	console.log(`[cnm] Downloading ${url}`);
109: 	await download(url, archivePath);
110: 	console.log(`[cnm] Downloading ${checksumsUrl}`);
111: 	await download(checksumsUrl, checksumsPath);
112: 	verifyFileChecksum(
113: 		archivePath,
114: 		archiveName,
115: 		parseChecksums(fs.readFileSync(checksumsPath, "utf8")),
116: 	);
117: 	extract(archivePath, extractDir, osName);
118: 
119: 	const binary = findBinary(extractDir, targetName);
120: 	if (!binary) {
121: 		throw new Error(`Unable to locate ${targetName} in extracted archive.`);
122: 	}
123: 
124: 	fs.copyFileSync(binary, targetPath);
125: 	if (process.platform !== "win32") {
126: 		fs.chmodSync(targetPath, 0o755);
127: 	}
128: 	console.log(`[cnm] Installed ${targetName} to ${targetPath}`);
129: }
130: 
131: main().catch((error) => {
132: 	console.error(
133: 		`[cnm] ${error instanceof Error ? error.message : String(error)}`,
134: 	);
135: 	process.exitCode = 1;
136: });

