text:
  1: package providers
  2: 
  3: import (
  4: 	runtimex "github.com/ByteTrue/commit-now-myfriend/internal/runtime"
  5: )
  6: 
  7: func toolDescription(name runtimex.ToolName) string {
  8: 	switch name {
  9: 	case runtimex.ToolInspectCommitScope:
 10: 		return "Inspect the current Commit Scope: changed files, secret blockers, AI exposure summary. Call this first."
 11: 	case runtimex.ToolGetDiff:
 12: 		return "Return the unified diff for the selected Commit Scope. Use to understand what changed."
 13: 	case runtimex.ToolReadFile:
 14: 		return "Read a single file from the working tree within the Read Budget. Required before repair_file."
 15: 	case runtimex.ToolPreviewCommit:
 16: 		return "Preview a single commit message without staging or creating it."
 17: 	case runtimex.ToolCreateCommits:
 18: 		return "Create one or more local commits from the selected Commit Scope. Each selected file must belong to exactly one commit. Use conservative file-level splits."
 19: 	case runtimex.ToolRepairFile:
 20: 		return "Write resolved content to an eligible conflicted file. Only allowed inside the Full-screen TUI Interactive Repair flow."
 21: 	case runtimex.ToolFinish:
 22: 		return "Finish the workflow after commits have been created (or the dry-run preview is acceptable)."
 23: 	case runtimex.ToolAbort:
 24: 		return "Abort the workflow with a human-readable reason. Use when the task cannot be completed safely."
 25: 	}
 26: 	return "cnm domain tool"
 27: }
 28: 
 29: func toolSchema(name runtimex.ToolName) map[string]any {
 30: 	switch name {
 31: 	case runtimex.ToolInspectCommitScope, runtimex.ToolGetDiff:
 32: 		return map[string]any{
 33: 			"type":       "object",
 34: 			"properties": map[string]any{},
 35: 		}
 36: 	case runtimex.ToolReadFile:
 37: 		return map[string]any{
 38: 			"type": "object",
 39: 			"properties": map[string]any{
 40: 				"path": map[string]any{"type": "string", "description": "Repository-relative path of the file to read."},
 41: 			},
 42: 			"required": []string{"path"},
 43: 		}
 44: 	case runtimex.ToolPreviewCommit:
 45: 		return map[string]any{
 46: 			"type": "object",
 47: 			"properties": map[string]any{
 48: 				"message": map[string]any{"type": "string", "description": "Proposed commit message to preview."},
 49: 			},
 50: 			"required": []string{"message"},
 51: 		}
 52: 	case runtimex.ToolCreateCommits:
 53: 		return map[string]any{
 54: 			"type": "object",
 55: 			"properties": map[string]any{
 56: 				"kind": map[string]any{
 57: 					"type":        "string",
 58: 					"description": "single or file_split. Default single.",
 59: 					"enum":        []string{"single", "file_split"},
 60: 				},
 61: 				"commits": map[string]any{
 62: 					"type":        "array",
 63: 					"description": "Ordered list of commits to create.",
 64: 					"items": map[string]any{
 65: 						"type": "object",
 66: 						"properties": map[string]any{
 67: 							"message": map[string]any{"type": "string", "description": "Full commit message (subject only, or subject + body)."},
 68: 							"files":   map[string]any{"type": "array", "items": map[string]any{"type": "string"}, "description": "Repository-relative file paths included in this commit."},
 69: 						},
 70: 						"required": []string{"message", "files"},
 71: 					},
 72: 				},
 73: 				"splitLimitations": map[string]any{
 74: 					"type":        "array",
 75: 					"description": "Optional notes about why the model could not split further.",
 76: 					"items": map[string]any{
 77: 						"type": "object",
 78: 						"properties": map[string]any{
 79: 							"code":     map[string]any{"type": "string"},
 80: 							"message":  map[string]any{"type": "string"},
 81: 							"fallback": map[string]any{"type": "string"},
 82: 						},
 83: 						"required": []string{"code", "message"},
 84: 					},
 85: 				},
 86: 			},
 87: 			"required": []string{"commits"},
 88: 		}
 89: 	case runtimex.ToolRepairFile:
 90: 		return map[string]any{
 91: 			"type": "object",
 92: 			"properties": map[string]any{
 93: 				"path":    map[string]any{"type": "string", "description": "Eligible conflicted file path."},
 94: 				"content": map[string]any{"type": "string", "description": "Full resolved file content (no conflict markers)."},
 95: 			},
 96: 			"required": []string{"path", "content"},
 97: 		}
 98: 	case runtimex.ToolFinish:
 99: 		return map[string]any{
100: 			"type": "object",
101: 			"properties": map[string]any{
102: 				"message": map[string]any{"type": "string", "description": "Optional final message."},
103: 			},
104: 		}
105: 	case runtimex.ToolAbort:
106: 		return map[string]any{
107: 			"type": "object",
108: 			"properties": map[string]any{
109: 				"message": map[string]any{"type": "string", "description": "Reason the workflow was aborted."},
110: 			},
111: 			"required": []string{"message"},
112: 		}
113: 	}
114: 	return map[string]any{"type": "object", "properties": map[string]any{}}
115: }

