text:
  1: package tui
  2: 
  3: import (
  4: 	"fmt"
  5: 	"strings"
  6: 
  7: 	"github.com/ByteTrue/commit-now-myfriend/internal/config"
  8: 	tea "github.com/charmbracelet/bubbletea"
  9: )
 10: 
 11: type ConfigPanelInput struct {
 12: 	Width      int
 13: 	Height     int
 14: 	NoColor    bool
 15: 	Effective  config.EffectiveConfig
 16: 	Sources    config.ConfigSourceSummary
 17: 	UserPath   string
 18: 	WriteValue func(key config.ConfigKey, value string) error
 19: 	UnsetValue func(key config.ConfigKey) error
 20: 	Reload     func() (config.EffectiveConfig, config.ConfigSourceSummary, error)
 21: }
 22: 
 23: type ConfigPanelResult struct {
 24: 	Cancelled bool
 25: 	Saved     int
 26: 	LastError string
 27: }
 28: 
 29: type configPanelScreen int
 30: 
 31: const (
 32: 	configScreenList configPanelScreen = iota
 33: 	configScreenEdit
 34: 	configScreenChoice
 35: )
 36: 
 37: type ConfigPanelModel struct {
 38: 	width   int
 39: 	height  int
 40: 	theme   Theme
 41: 	input   ConfigPanelInput
 42: 	cursor  int
 43: 	screen  configPanelScreen
 44: 	editKey config.ConfigKey
 45: 	editBuf string
 46: 	choices []string
 47: 	choice  int
 48: 	status  string
 49: 	saved   int
 50: 	cancel  bool
 51: }
 52: 
 53: func NewConfigPanelModel(input ConfigPanelInput) ConfigPanelModel {
 54: 	width := input.Width
 55: 	if width <= 0 {
 56: 		width = 96
 57: 	}
 58: 	height := input.Height
 59: 	if height <= 0 {
 60: 		height = 30
 61: 	}
 62: 	return ConfigPanelModel{
 63: 		width:  width,
 64: 		height: height,
 65: 		theme:  Theme{NoColor: input.NoColor},
 66: 		input:  input,
 67: 		screen: configScreenList,
 68: 	}
 69: }
 70: 
 71: func (m ConfigPanelModel) Init() tea.Cmd { return nil }
 72: 
 73: func (m ConfigPanelModel) Result() ConfigPanelResult {
 74: 	return ConfigPanelResult{Cancelled: m.cancel, Saved: m.saved, LastError: m.status}
 75: }
 76: 
 77: func (m ConfigPanelModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
 78: 	switch msg := msg.(type) {
 79: 	case tea.WindowSizeMsg:
 80: 		if msg.Width > 0 {
 81: 			m.width = msg.Width
 82: 		}
 83: 		if msg.Height > 0 {
 84: 			m.height = msg.Height
 85: 		}
 86: 		return m, nil
 87: 	case tea.KeyMsg:
 88: 		return m.handleKey(msg)
 89: 	}
 90: 	return m, nil
 91: }
 92: 
 93: func (m ConfigPanelModel) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
 94: 	switch m.screen {
 95: 	case configScreenList:
 96: 		return m.handleListKey(msg)
 97: 	case configScreenEdit:
 98: 		return m.handleEditKey(msg)
 99: 	case configScreenChoice:
100: 		return m.handleChoiceKey(msg)
101: 	}
102: 	return m, nil
103: }
104: 
105: func (m ConfigPanelModel) handleListKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
106: 	switch msg.Type {
107: 	case tea.KeyCtrlC:
108: 		m.cancel = true
109: 		return m, tea.Quit
110: 	case tea.KeyRunes:
111: 		s := msg.String()
112: 		switch s {
113: 		case "q":
114: 			m.cancel = true
115: 			return m, tea.Quit
116: 		case "j":
117: 			m.moveCursor(1)
118: 		case "k":
119: 			m.moveCursor(-1)
120: 		case "d":
121: 			return m.startUnset()
122: 		}
123: 	case tea.KeyUp:
124: 		m.moveCursor(-1)
125: 	case tea.KeyDown:
126: 		m.moveCursor(1)
127: 	case tea.KeyEnter:
128: 		return m.startEdit()
129: 	}
130: 	return m, nil
131: }
132: 
133: func (m *ConfigPanelModel) moveCursor(delta int) {
134: 	keys := config.ConfigKeys
135: 	next := m.cursor + delta
136: 	if next < 0 {
137: 		next = 0
138: 	}
139: 	if next >= len(keys) {
140: 		next = len(keys) - 1
141: 	}
142: 	m.cursor = next
143: }
144: 
145: func (m ConfigPanelModel) startEdit() (tea.Model, tea.Cmd) {
146: 	key := config.ConfigKeys[m.cursor]
147: 	choices := configChoiceList(key)
148: 	if len(choices) > 0 {
149: 		m.screen = configScreenChoice
150: 		m.editKey = key
151: 		m.choices = choices
152: 		m.choice = 0
153: 		current := stringFromPointer(config.GetConfigValue(m.input.Effective, key))
154: 		for i, c := range choices {
155: 			if c == current {
156: 				m.choice = i
157: 				break
158: 			}
159: 		}
160: 		return m, nil
161: 	}
162: 	m.screen = configScreenEdit
163: 	m.editKey = key
164: 	current := config.GetConfigValue(m.input.Effective, key)
165: 	if current != nil && key != config.ConfigKeyAPIKey {
166: 		m.editBuf = *current
167: 	} else {
168: 		m.editBuf = ""
169: 	}
170: 	return m, nil
171: }
172: 
173: func (m *ConfigPanelModel) reloadEffective() {
174: 	if m.input.Reload == nil {
175: 		return
176: 	}
177: 	values, sources, err := m.input.Reload()
178: 	if err != nil {
179: 		m.status = "reload error: " + err.Error()
180: 		return

